// Üretilen dosya: tool/ozgun/uret.py. Tarih · Orta Asya Türk devletleri ve göçler (Hun, Göktürk, Uygur, Hazar, Avar) (orta).
const ozHistory6Orta = <(String, String, List<String>, String)>[
  ('Orta Asya\'dan yapılan göçlerin nedenlerinden hangisi siyasi nitelikte bir nedendir?', 'Çin baskısı ve boylar arasındaki mücadeleler', ['Bozkırda yağışların azalması', 'Salgın hayvan hastalıklarının yayılması', 'Nüfusun otlakların taşıyabileceğinden hızlı artması'], 'Kuraklık ve salgın doğal, nüfus artışı ekonomik-toplumsal nedenlerdir. Çin\'in ve güçlü boyların baskısı ise siyasi bir nedendir.'),
  ('Orta Asya\'dan yapılan göçlerin sonuçları arasında aşağıdakilerden hangisi gösterilemez?', 'Türklerin Orta Asya\'yı tümüyle boşaltması', ['Türk kültürünün geniş bir coğrafyaya yayılması', 'Gidilen yerlerde yeni Türk devletlerinin kurulması', 'Bazı Türk topluluklarının zamanla yerel halklar içinde erimesi'], 'Göçlere rağmen Orta Asya\'da Türk nüfusu yaşamayı sürdürmüştür; diğer seçenekler göçlerin bilinen sonuçlarıdır.'),
  ('Göçebe bozkır toplumlarında yerleşik toplumlara göre aşağıdakilerden hangisi daha az gelişmiştir?', 'Anıtsal mimari ve kalıcı kent yapıları', ['Atçılık ve hayvan yetiştiriciliği', 'Taşınabilir eşya ve süsleme sanatı', 'Hareketli askerî örgütlenme'], 'Sürekli yer değiştiren toplumlar büyük taş yapılar yerine taşınabilir eşyalara yönelmiştir; bu yüzden anıtsal mimari yerleşik toplumlardaki kadar gelişmemiştir.'),
  ('Bir tarih öğretmeni \'Orta Asya\'dan çevreye doğru yapılan göçler Türk tarihinin dünya tarihine katılmasını sağlamıştır\' diyor. Bu yargıyı en iyi destekleyen örnek aşağıdakilerden hangisidir?', 'Avrupa Hunlarının batıya ilerleyişiyle Kavimler Göçü\'nün başlaması', ['Mısır\'da piramitlerin yapılması', 'Çin\'de kâğıdın icat edilip doğu ve batıya yayılması', 'Fenikelilerin alfabeyi geliştirmesi'], 'Hunların 375\'te Karadeniz\'in kuzeyine gelmesi Avrupa\'da Kavimler Göçü\'nü başlatmış ve Avrupa tarihinin akışını değiştirmiştir.'),
  ('Orta Asya\'dan doğuya, Çin yönüne giden Türk topluluklarıyla ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Bir bölümü Kuzey Çin\'de hanedanlar kurmuş ve zamanla Çin kültürü içinde erimiştir', ['Japonya\'ya geçerek orada ilk devleti kurmuşlardır', 'Çin\'i tümüyle Türkleştirmişlerdir', 'Herhangi bir siyasi yapı kuramadan kısa sürede dağılıp Orta Asya\'ya geri dönmüşlerdir'], 'Tabgaçlar gibi Türk kökenli topluluklar Kuzey Çin\'de hanedan kurmuş, ancak kalabalık Çin nüfusu içinde zamanla asimile olmuştur.'),
  ('Mete\'nin \'Toprak devletin temelidir, onu kimseye veremem\' anlamına gelen tavrı, eski Türk devlet anlayışındaki hangi ilkeyi yansıtır?', 'Vatan toprağının pazarlık konusu yapılamayacağını', ['Hükümdarın mallarının halka ait olduğunu', 'Dinin devlet işlerinden ayrı tutulduğunu', 'Ülkenin hanedan üyeleri arasında paylaştırıldığını'], 'Mete at ve hatun gibi kişisel değerleri vermiş, ancak toprağı vermeyi reddetmiştir; bu, toprağın devletin ortak ve vazgeçilmez varlığı sayıldığını gösterir.'),
  ('Mete\'nin 26 kavmi tek yönetim altında toplaması Türk tarihi açısından neden önemli sayılır?', 'Orta Asya\'daki Türk boylarının ilk kez tek bir devlet çatısı altında birleştirilmesi', ['Türklerin İslamiyet\'i kabul etmesine zemin hazırlayan ilk adım olması', 'Türk alfabesinin icadına zemin hazırlaması', 'Hunların batıya göçünü sona erdirmesi'], 'Mete döneminde dağınık boylar tek siyasi birlik altında toplanmış; bu durum Türk siyasi birliğinin ilk büyük örneği olarak değerlendirilir.'),
  ('MÖ 200\'de Hun ordusunun Çin imparatoru Kao-ti\'yi (Liu Bang) Pai-teng\'de kuşatması hangi sonuca yol açmıştır?', 'Çin\'in Hunlara yıllık vergi ödeyip prenses vermeyi kabul etmesi', ['Hunların Çin\'e bağlanması', 'Çin Seddi\'nin yıkılması', 'Hun başkentinin Çin sınırındaki bir kente taşınarak yerleşik hayata geçilmesi'], 'Kuşatmadan kurtulmak için anlaşma yapan Han hanedanı, Hunlara ipek, tahıl gibi düzenli hediyeler vermeyi ve hanedan kızlarından evlilik göndermeyi kabul etmiştir.'),
  ('Çin\'in Hunlara prenses gelin göndererek ve hediyeler vererek barış sağlamaya çalışması, Çin\'in o dönemki dış politikası hakkında ne gösterir?', 'Hunları askerî yoldan yenemeyince diplomasi ve kültürel etkiyle yumuşatmayı denediğini', ['Hunlara karşı hiçbir askerî kaygı taşımadığını', 'Hunları tamamen kendi topraklarına katıp eyalet hâline getirdiğini', 'Hunlarla ticareti tümüyle yasakladığını'], 'Prenses evlilikleri ve hediyeler, askerî üstünlüğü bulunan Hunları barışçı yollarla oyalamaya ve saray içine Çin etkisini sokmaya dönük bir politikadır.'),
  ('Çin\'in Hunlara karşı uzun bir sur hattı inşa etmesi iki toplum arasındaki güç dengesi hakkında hangi çıkarımı destekler?', 'Çin\'in açık sahada Hun süvarilerine karşı zorlandığını', ['Hunların denizden saldırdığını', 'Çin\'in Hunlara karşı her savaşta kolayca üstün geldiğini', 'Hunların hiç akın düzenlemediğini'], 'Hareketli atlı ordulara karşı savunmaya geçmek için böyle büyük bir yapıya başvurulması, açık savaşta Hunların ciddi bir tehdit olduğunu gösterir.'),
  ('Hunların Çin ile ilişkilerinde ipek ve tahıl gibi ürünlerin yanında Çin\'e karşılığında en çok sağladığı mal hangisiydi?', 'At', ['Pirinç', 'Porselen', 'Çay'], 'Çin\'in süvari ihtiyacı nedeniyle bozkırdan at almak istemesi, sınır pazarlarında at-ipek takasını önemli kılmıştır.'),
  ('Asya Hunlarında hükümdarın unvanı Çin kaynaklarında hangi biçimde geçer?', 'Tanhu (Şanyü)', ['Kağan (Hakan)', 'Sultan', 'Raca'], 'Çin kaynakları Hun hükümdarını \'Tanhu\' (Shanyu) olarak anar. \'Kağan\' unvanı daha sonra Avarlar ve Göktürklerle yaygınlaşmıştır.'),
  ('Ötüken\'in birçok Türk devletince yönetim merkezi seçilmesinin anlamı aşağıdakilerden hangisidir?', 'Burayı elinde tutanın Türk dünyasında meşru egemen sayılması', ['Bölgenin denize en yakın yer olması', 'Bölgede Çin kökenli nüfusun çoğunlukta bulunması ve tarımın gelişmiş olması', 'Ticaret yollarından tamamen uzak olması'], 'Ötüken kutsal bir yer olarak görülmüş, burayı denetleyen devlet bozkırın asıl sahibi kabul edilmiştir. Orhun yazıtları da Ötüken\'in önemini vurgular.'),
  ('Asya Hunlarının MS 48\'de Kuzey ve Güney olarak ikiye ayrılmasının ardından Güney Hunlarının durumu için aşağıdakilerden hangisi doğrudur?', 'Çin\'in himayesine girip zamanla Çin içinde etkisini yitirdiler', ['Avrupa\'ya göç ederek Attila\'nın devletini kurdular', 'Göktürk Devleti\'ni kurup Ötüken\'i yeniden merkez yaptılar', 'Hindistan\'ı fethettiler'], 'Güney Hunları Çin\'e bağlanmış ve sınır bölgelerine yerleşmiştir; bir kısmı daha sonra Kuzey Çin\'de kısa ömürlü devletler kurmuştur.'),
  ('Asya Hun Devleti\'nin zayıflamasında aşağıdaki etkenlerden hangisi en belirleyici olmuştur?', 'Taht kavgaları ve Çin\'in boyları birbirine düşürme siyaseti', ['Denizden gelen istilalar', 'Salgın bir veba yüzünden Hun nüfusunun neredeyse tamamen yok olması', 'İslamiyet\'in kabulüyle çıkan mezhep çatışmaları'], 'Hunlarda veraset belirsizliği taht kavgalarına yol açmış, Çin de bu bölünmeleri körükleyerek devleti zayıflatmıştır.'),
  ('Kuzey Hunlarının MS 2. yüzyılda Çin ve Siyenpi baskısı karşısında Orta Asya\'dan batıya doğru çekilmesi, sonraki yüzyıllarda hangi gelişmeyle ilişkilendirilir?', 'Hun topluluklarının İdil boylarına ulaşması ve Avrupa Hunlarının ortaya çıkması', ['Göktürklerin Ötüken\'de devlet kurması', 'Uygurların Maniheizmi devlet dini olarak kabul etmesi', 'Hazarların Yahudiliği benimsemesi'], 'Batıya çekilen Hun kolları uzun bir süreç sonunda Hazar\'ın kuzeyine ulaşmış; 4. yüzyılda Avrupa\'ya giren Hunlar bu göç zincirine bağlanır.'),
  ('Türk tarihçilerinin Türk kökenli saydığı, 386–534 arasında Kuzey Çin\'de hüküm sürüp Budizmi destekleyen hanedanı kuran topluluk hangisidir?', 'Tabgaçlar (Tobalar)', ['Uygurlar', 'Kırgızlar', 'Peçenekler (Patzinaklar)'], 'Tabgaçlar Kuzey Wei hanedanını kurmuştur. Bu topluluğun adı o kadar yerleşmiştir ki sonraki Türk yazıtlarında Çin\'e \'Tabgaç\' denmiştir.'),
  ('Orhun yazıtlarında Çin ve Çinliler için kullanılan ad, Kuzey Çin\'i bir dönem yönetmiş hangi topluluğun adından gelir?', 'Tabgaç', ['Tunguz', 'Juan-juan', 'Yüeçi'], 'Kuzey Çin\'i uzun süre yöneten Tabgaçların adı, Türkler arasında Çin\'in genel adı olarak kullanılmaya başlanmış ve Göktürk yazıtlarına da bu biçimde geçmiştir.'),
  ('Tabgaçların Kuzey Çin\'de kalabalık bir nüfusu yönetirken zamanla Çin dilini, giyimini ve adlarını benimsemesi hangi kavramla açıklanır?', 'Asimilasyon', ['Feodalleşme', 'Merkezîleşme ve bürokratikleşme', 'Sömürgecilik'], 'Tabgaç yöneticileri Çinli tebaa arasında sayıca az kalmış ve resmî politikalarla Çin kültürünü benimseyince kendi kimliklerini yitirmiştir.'),
  ('Hunların 375\'te Karadeniz\'in kuzeyinde ilk olarak yenip önlerinden sürdüğü Germen topluluğu aşağıdakilerden hangisidir?', 'Ostrogotlar (Doğu Gotları)', ['Franklar', 'Anglo-Saksonlar (Angıllar)', 'Vandallar'], 'Hunlar önce Alanları, sonra Ermanarik yönetimindeki Ostrogotları yenmiştir. Ostrogotların ve ardından Vizigotların batıya kaçışı Kavimler Göçü\'nü başlatmıştır.'),
  ('395 yılında Kafkasları aşarak Doğu Anadolu ve Urfa çevresine kadar akın yapan, böylece Anadolu\'ya ilk Türk akınlarını gerçekleştiren Avrupa Hun komutanları kimlerdir?', 'Basık ve Kursık', ['Attila ve Bleda', 'Bumin ve İstemi', 'İlek ve Dengizik'], 'Avrupa Hunlarının Basık ve Kursık adlı komutanları 395–398 arasında Kafkasları geçerek Anadolu ve Suriye\'ye kadar akın yapmıştır; bunlar Anadolu\'ya yapılan ilk Türk akınları sayılır.'),
  ('Hun akınlarının sürdüğü 395 yılında Roma İmparatorluğu\'nun Doğu ve Batı olarak kalıcı biçimde ikiye ayrılması, Hunlar açısından nasıl bir ortam yaratmıştır?', 'İki ayrı Roma yönetimini birbirine karşı kullanma ve vergi alma imkânı', ['Hunların Roma\'ya tümüyle bağlanması', 'Hunların Avrupa\'dan çekilip Orta Asya\'ya dönmek zorunda kalması', 'Hunların Hristiyanlığı kabul etmesi'], 'Bölünmüş Roma\'nın iki yarısı ayrı ayrı politika izlemiş; Hunlar özellikle Doğu Roma\'dan antlaşmalarla yıllık vergi almış, Batı Roma ile de zaman zaman iş birliği yapmıştır.'),
  ('Avrupa Hunlarının merkezini Macaristan ovasına (Pannonia) taşıyan ve Doğu Roma\'yı yıllık vergiye bağlayan, Attila\'dan önceki hükümdar kimdir?', 'Rua', ['Balamir', 'Dengizik', 'İrnek'], 'Uldız\'dan sonra Hun tahtına geçen Rua, devletin merkezini Macaristan ovasına almış ve Doğu Roma\'yı vergiye bağlamıştır. 434\'te ölümü üzerine Attila ve Bleda başa geçmiştir.'),
  ('435\'te Doğu Roma ile Hunlar arasında yapılan ve Türk tarihinde Bizans\'la imzalanan ilk antlaşma kabul edilen antlaşma hangisidir?', 'Margus Antlaşması', ['Anatolios Antlaşması', 'Verdun Antlaşması', 'Nikea Antlaşması'], 'Attila ve Bleda döneminde imzalanan Margus Antlaşması\'yla Bizans yıllık vergiyi artırmış, Hun kaçaklarını iade etmeyi ve Hun tüccarlarına pazar açmayı kabul etmiştir.'),
  ('Margus Antlaşması\'nın maddeleri arasında Bizans\'ın Hunlara sığınan kaçakları geri vermeyi kabul etmesi, Hunların hangi kaygısını yansıtır?', 'Kendi otoritelerinden kaçan boy ve beylerin rakip güçlerle birleşmesini önlemek', ['Bizans\'ın Hunların topraklarında Hristiyanlığı yaymasını engellemek', 'Hun nüfusunu Bizans\'a göç ettirmek', 'Bizans\'tan denizcilik bilgisi almak'], 'Kaçakların iadesi şartı, Hun hükümdarının bağlı boylar üzerindeki denetimini korumak ve muhalif unsurların Bizans\'ta üslenmesini engellemek amacını taşır.'),
  ('447\'de Balkanlarda Bizans\'ı ağır yenilgiye uğratan Attila\'nın ardından imzalanan ve Bizans\'ın ödediği vergiyi daha da artıran antlaşma hangisidir?', 'Anatolios Antlaşması', ['Margus Antlaşması', 'Nedao Antlaşması', 'Kadeş Antlaşması'], 'Attila\'nın Balkan seferlerinden sonra imzalanan Anatolios Antlaşması ile Bizans yıllık vergiyi artırmış ve Tuna\'nın güneyinde geniş bir bölgeyi boşaltmayı kabul etmiştir.'),
  ('449\'da Bizans elçilik heyetiyle Attila\'nın sarayına giden ve Hun sarayındaki yaşamı ayrıntılı biçimde anlatan tarihçi kimdir?', 'Priskos', ['Herodotos', 'Prokopios', 'Menandros'], 'Priskos, Attila\'nın sarayında gördüğü sade yaşamı, ziyafetleri ve diplomatik usulleri kaleme almış; bu anlatım Avrupa Hunları için temel kaynaklardandır.'),
  ('Priskos\'un anlatımına göre Attila\'nın ziyafetlerde konukları altın ve gümüş kaplarla ağırlarken kendisinin tahta kap kullanması ve sade giyinmesi, hükümdarın hangi özelliğini öne çıkarır?', 'Gösterişten uzak, halkına yakın bir yönetici imajını', ['Sarayın yoksul olduğunu', 'Attila\'nın ziyafetlere hiç katılmadığını ve konukları yalnız bıraktığını', 'Hunların maden işlemeyi bilmediğini'], 'Konuklarına zengin sofra kurdurup kendisi sade yaşayan Attila, cömertliği ve sadeliğiyle saygınlık kazanmayı amaçlayan bir hükümdar olarak anlatılır.'),
  ('Attila\'nın Doğu Roma\'yı ağır vergiye bağlamasının ardından Batı\'ya yönelmesinde, Batı Roma imparatorunun kız kardeşi Honoria\'nın Attila\'ya yüzük göndermesi ve Attila\'nın bunu evlilik teklifi sayması nasıl bir rol oynamıştır?', 'Attila\'ya çeyiz olarak Batı Roma topraklarının yarısını isteme gerekçesi vermiştir', ['Hunlarla Batı Roma\'yı kalıcı bir ittifaka bağlamıştır', 'Attila\'nın Hristiyanlığa geçip Roma kilisesine bağlanmasına yol açmıştır', 'Hunların Pannonia\'dan çekilmesine neden olmuştur'], 'Attila, Honoria\'nın gönderdiği yüzüğü evlilik isteği olarak yorumlamış ve çeyiz olarak Batı Roma\'nın yarısını talep edince reddedilmesini sefer için gerekçe yapmıştır.'),
  ('Katalon Ovası Savaşı\'nda her iki tarafta da Germen kavimlerinin bulunması, dönemin siyasi yapısı hakkında neyi gösterir?', 'Germen toplulukların ortak bir cephe yerine kendi çıkarlarına göre farklı güçlerle ittifak kurduğunu', ['Germenlerin Hunlara karşı tek vücut olduğunu', 'Roma\'nın Germen kavimleriyle hiçbir koşulda iş birliği yapmadığını ve onları dışladığını', 'Hunların yalnız kendi boylarıyla savaştığını'], 'Ostrogot ve Gepidler Hunlarla, Vizigot ve Franklar Roma ile birlikte savaşmıştır; bu, ittifakların etnik değil siyasi çıkarlara dayandığını gösterir.'),
  ('452\'de İtalya\'ya giren Attila\'nın Roma önlerinde geri dönmesinden önce görüştüğü kişi kimdir?', 'Papa I. Leo', ['İmparator Valens', 'Kral Theodorik', 'Papa I. Gregorius'], 'Attila\'nın kuzey İtalya\'daki kentleri almasından sonra Papa I. Leo bir heyetle onunla görüşmüş, Attila da İtalya\'dan çekilmiştir.'),
  ('Attila\'nın 452\'de İtalya\'dan geri çekilmesinin nedenleri arasında tarihçilerin en çok üzerinde durduğu etken aşağıdakilerden hangisidir?', 'Orduda baş gösteren salgın ve kıtlık', ['Hunların denizde yenilmesi', 'Attila\'nın Hristiyanlığı kabul edip dinî bir yemin etmesi', 'Çin\'in Hun yurduna saldırması'], 'Kaynaklar, İtalya\'daki kıtlık ve salgın hastalığın Hun ordusunu yıprattığını ve Papa ile yapılan görüşmenin de etkisiyle Attila\'nın geri döndüğünü belirtir.'),
  ('Avrupalı yazarların Attila için kullandığı \'Tanrı\'nın Kırbacı\' (Flagellum Dei) nitelemesi en iyi hangi biçimde yorumlanır?', 'Hristiyan Avrupa\'nın onun akınlarını ilahi bir ceza olarak görmesi', ['Attila\'nın kendisine bizzat verdiği ve paralarına yazdırdığı resmî unvan olması', 'Hunların bir Hristiyan tarikatı kurması', 'Attila\'nın Roma\'da piskopos seçilmesi'], 'Bu niteleme, Hun akınlarını günahların cezası sayan Hristiyan yazarların bakış açısını yansıtır; Hunların kendi kullandığı bir unvan değildir.'),
  ('Attila\'nın 453\'te ölümünün ardından Avrupa Hun Devleti\'nin hızla dağılmasının en önemli nedeni nedir?', 'Oğulları arasındaki taht kavgası ve bağlı Germen kavimlerinin ayaklanması', ['Hunların toptan Çin\'e dönmesi', 'Bizans\'ın Hun yurdunu ilhak ederek doğrudan yönetimine alması', 'Hun ordusunun denizde batması'], 'Attila\'nın oğulları İlek, Dengizik ve İrnek arasındaki çekişme, Gepid önderliğindeki bağlı kavimlerin ayaklanmasıyla birleşince devlet çözülmüştür.'),
  ('Attila\'nın küçük oğlu İrnek ve ona bağlı Hun kalıntılarının Karadeniz\'in kuzeyine çekilmesi, sonraki dönemde hangi toplulukların tarih sahnesine çıkışıyla ilişkilendirilir?', 'Bulgar Türkleri', ['Göktürkler', 'Uygurlar', 'Karluklar'], 'İrnek\'in yönettiği Hun kalıntılarının Karadeniz\'in kuzeyindeki Ogur boylarıyla kaynaşması, Bulgarların ortaya çıkışıyla bağlantılı görülür.'),
  ('Bir öğrenci \'Hunlar Batı Roma\'yı yıkmasa da yıkılışında dolaylı rol oynamıştır\' diyor. Bu yargıyı en iyi destekleyen gerekçe hangisidir?', 'Hun baskısıyla yerinden oynayan Germen kavimlerinin Roma topraklarını işgal etmesi', ['Attila\'nın Roma kentini yerle bir etmesi', 'Hunların Batı Roma\'nın son imparatorunu tahttan indirip yerine kendi adamlarını geçirmesi', 'Hunların Roma\'ya karşı denizden abluka uygulaması'], '476\'da Batı Roma\'yı Germen kökenli Odoakr sona erdirmiştir. Hunların payı, Germen kavimlerini Roma topraklarına iterek imparatorluğu zayıflatmalarıdır.'),
  ('Avrupa Hunlarında bağlı kavimlerin kendi krallarıyla yönetilmeye devam edip Hun hükümdarına asker ve vergi vermesi, Hun yönetim anlayışının hangi özelliğini gösterir?', 'Fethedilen toplulukların iç işlerine fazla karışmayan, gevşek bir egemenlik', ['Bütün kavimleri zorla tek dine geçiren bir yönetim', 'Fethedilen halkları sürgün eden bir politika', 'Her kente bir Hun valisi atayan, vergileri merkezden toplayan bürokratik bir yönetim'], 'Ostrogot, Gepid gibi kavimler kendi krallarını korumuş; Hunlar onlardan bağlılık, asker ve vergi istemiştir. Bu esnek yapı aynı zamanda devletin hızla dağılmasını kolaylaştırmıştır.'),
  ('Avrupa Hunları ile Asya Hunlarının yönetim anlayışları arasında ortak olan özellik aşağıdakilerden hangisidir?', 'Komşu yerleşik devletleri vergiye bağlayan atlı-göçebe bir askerî güç olmaları', ['Her ikisinin de İslamiyet\'i kabul etmesi', 'Her ikisinin de deniz filosuna dayanması', 'Her ikisinin de Göktürk alfabesiyle yazıt dikerek tarihlerini kayda geçirmesi'], 'Asya Hunları Çin\'den, Avrupa Hunları Bizans\'tan düzenli vergi almıştır; ikisi de atlı okçu ordulara dayanan bozkır devletleridir.'),
  ('Ak Hunlar (Eftalitler) devletlerini ilk olarak hangi bölgede kurmuştur?', 'Toharistan (Amuderya\'nın yukarı havzası)', ['Macaristan ovası', 'Ötüken (Orhun vadisi çevresi)', 'İdil boyu'], 'Ak Hunlar 5. yüzyılda Toharistan çevresinde güçlenmiş, buradan İran ve Hindistan\'a doğru genişlemiştir.'),
  ('Ak Hun Devleti 6. yüzyılın ortalarında hangi iki gücün ortak saldırısıyla yıkılmıştır?', 'Göktürkler ve Sasaniler', ['Bizans ve Avarlar', 'Çin ve Uygurlar', 'Araplar ve Hazar Kağanlığı'], 'Göktürk İstemi Yabgu ile Sasani hükümdarı Hüsrev Anuşirvan ittifak kurmuş, Ak Hunları yenerek topraklarını aralarında paylaşmışlardır.'),
  ('Göktürklerle Sasanilerin Ak Hun topraklarını paylaşması sonrasında, iki devlet arasındaki ortak sınırın hangi nehir olduğu kabul edilir?', 'Amuderya (Ceyhun)', ['Tuna', 'İdil', 'Sarı Irmak (Huang He)'], 'Ak Hunların yıkılmasıyla Göktürkler ile Sasaniler Amuderya boyunda komşu olmuş; bu komşuluk kısa süre sonra İpek Yolu yüzünden rekabete dönüşmüştür.'),
  ('Ak Hunların Sasanileri bir dönem vergiye bağlaması ve Hindistan\'a akınlar yapması birlikte düşünüldüğünde, bu devletin hangi bölge için önemli bir güç olduğu söylenebilir?', 'İran ile Hindistan arasındaki ticaret ve geçiş bölgesi', ['Akdeniz\'in batı kıyıları', 'Sibirya\'nın kuzeyindeki ormanlar ve Kuzey Buz Denizi kıyıları', 'Japon denizi kıyıları'], 'Toharistan merkezli Ak Hunlar hem İran\'a hem Hindistan\'a uzanarak Orta Asya ile Güney Asya arasındaki geçiş yollarını denetlemiştir.'),
  ('Göktürkler bağımsızlıklarını kazanmadan önce hangi devlete bağlı olarak yaşıyor ve onun için demircilik yapıyordu?', 'Juan-juan (Asya Avar) Kağanlığı', ['Asya Hun Devleti\'nin son kolu olan Kuzey Hunları', 'Uygur Kağanlığı', 'Sasani İmparatorluğu ve onun doğu valileri'], 'Göktürkler Altay çevresinde Juan-juanlara bağlıydı ve onlara demir işçiliği yapıyordu; 552\'de bu egemenliğe son verdiler.'),
  ('Bumin\'in Juan-juan hükümdarından kız istemesi üzerine \'Sen benim demircimsin\' diye aşağılanması ne ile sonuçlanmıştır?', 'Bumin\'in Çin\'deki Batı Wei ile ittifak kurup Juan-juanlara karşı ayaklanmasıyla', ['Bumin\'in Juan-juan sarayına esir olarak götürülüp orada ömrünü geçirmesiyle', 'Göktürklerin Avrupa\'ya göç ederek Pannonia\'ya yerleşmesiyle', 'İki devlet arasında kalıcı bir evlilik ve barış antlaşması imzalanmasıyla'], 'Hakarete uğrayan Bumin, Batı Wei hanedanından bir prensesle evlenip ittifak kurmuş ve 552\'de Juan-juanları yenerek bağımsız devletini ilan etmiştir.'),
  ('Bumin 552\'de Juan-juanları yenip bağımsızlığını ilan ettiğinde aldığı unvan aşağıdakilerden hangisidir?', 'İl Kağan', ['Tanhu', 'Yabgu', 'Ulu Tudun'], 'Bumin bağımsızlığını ilan ederek \'İl Kağan\' unvanını almış, ancak kısa süre sonra ölmüştür.'),
  ('İstemi Yabgu\'nun ipek ticaretini Sasani toprakları üzerinden yapmak için gönderdiği elçilik heyetine Sasani hükümdarının tepkisi ne olmuştur?', 'Getirilen ipekleri satın alıp elçilerin gözü önünde yaktırmıştır', ['İpeği Bizans\'a ulaştırmak için gümrüksüz geçiş izni vermiştir', 'Göktürklerle evlilik yoluyla akrabalık kurarak ticareti büyütmüştür', 'Kendi tüccarlarını Ötüken\'e göndererek ortak bir şirket kurmuştur'], 'Hüsrev Anuşirvan ipek ticaretinin Türklerin eline geçmesini istemediği için ipekleri satın alıp yaktırmış, ikinci heyetin bazı üyelerini de zehirletmiştir.'),
  ('Sasanilerin ipek ticaretini engellemesi üzerine İstemi Yabgu\'nun izlediği politika aşağıdakilerden hangisidir?', 'Bizans\'a elçi gönderip Sasanilere karşı ittifak ve doğrudan ticaret aramak', ['Sasanilerle birleşip Bizans\'ı kuşatmak ve İstanbul\'u ele geçirmeye çalışmak', 'İpek üretimini tümüyle durdurup yalnız hayvancılığa ağırlık vermek', 'Ticaret yolunu Hindistan üzerinden deniz yoluna çevirmek için donanma kurmak'], 'İstemi, Soğdlu Maniak başkanlığındaki bir heyeti 568\'de Bizans\'a göndermiş; böylece Sasanileri devre dışı bırakan bir Türk-Bizans yakınlaşması doğmuştur.'),
  ('İstemi Yabgu\'nun elçilik işlerinde Soğdlu bir tüccarı görevlendirmesi, Göktürk devlet yapısıyla ilgili hangi çıkarımı destekler?', 'Ticarette deneyimli yerleşik halkların bilgi ve becerilerinden yararlanıldığını', ['Göktürklerin kendi aralarında yazıyı hiç bilmediğini ve elçi yetiştiremediğini', 'Soğdluların Göktürk Devleti\'ni fiilen yönettiğini ve kağanı atadığını', 'Göktürklerin Bizans\'la yalnızca savaş yoluyla ilişki kurduğunu'], 'Soğdlular İpek Yolu ticaretinde uzmanlaşmış bir topluluktu; Göktürkler onların dil ve ticaret bilgisini diplomaside kullanmıştır.'),
  ('Göktürk-Bizans yakınlaşmasının iki devletin ortak çıkarı açısından en temel nedeni aşağıdakilerden hangisidir?', 'İkisinin de Sasani İmparatorluğu\'nu ortak rakip görmesi', ['İki devletin aynı dini paylaşması ve ortak bir kilise kurmak istemesi', 'Göktürklerin Bizans\'a bağlı bir eyalet olmayı kabul etmesi', 'Bizans\'ın Çin\'e karşı Göktürklerden donanma yardımı istemesi'], 'Bizans uzun süredir Sasanilerle savaşıyordu; Göktürkler de ipek ticaretini engelleyen Sasanilere karşıydı. Bu ortak düşman iki devleti yakınlaştırmıştır.'),
  ('İstemi Yabgu\'nun batı fetihleri sonucunda Göktürk Devleti\'nin sınırlarının batıda hangi bölgelere kadar ulaştığı kabul edilir?', 'Hazar Denizi\'nin kuzeyi ve Karadeniz\'e yakın bozkırlar', ['İspanya ve Kuzey Afrika kıyıları', 'Kızıldeniz kıyısındaki Arap kentleri', 'İskandinavya ve Baltık Denizi'], 'İstemi döneminde Göktürk egemenliği Hazar\'ın kuzeyindeki bozkırlara ve Kırım\'a kadar uzanmıştır; bu Göktürklerin en geniş sınırlarına işaret eder.'),
  ('Bumin\'in oğlu olan ve hükümdarlığı döneminde Göktürklerin doğuda en güçlü dönemini yaşadığı, Kitan ve Kırgızları bağımlı hâle getiren kağan kimdir?', 'Mukan Kağan', ['Kara Kağan', 'İşbara Kağan', 'Kapgan Kağan'], 'Mukan Kağan (553–572) Juan-juan kalıntılarını tasfiye etmiş, Kitan ve Kırgızları bağlamış, Kuzey Çin\'deki devletleri de vergiye bağlamıştır.'),
  ('Mukan Kağan döneminde Kuzey Çin\'deki iki rakip hanedanın Göktürklere hediye ve vergi vermek için yarışması, Göktürklere hangi avantajı sağlamıştır?', 'Çin\'in bölünmüşlüğünden yararlanarak iki tarafı da kendine bağlı tutma imkânı', ['Çin\'i tamamen fethedip Ötüken\'i Çin\'e taşıma imkânı', 'Çin\'le ticareti tümüyle yasaklayıp kendi ipeğini üretme imkânı', 'Çin\'e asker gönderip Budizmi orada yasaklama imkânı'], 'Kuzey Zhou ve Kuzey Qi birbirine karşı Göktürk desteği aradığından Göktürkler her iki taraftan da ipek ve hediye almıştır.'),
  ('Taspar Kağan döneminde Göktürk sarayında Budizme ilgi duyulması ve Budist metinlerin çevrilmesi, Göktürk-Çin ilişkilerinin hangi boyutunu yansıtır?', 'Kültürel ve dinî etkileşimin askerî-siyasi ilişkilerin yanında sürdüğünü', ['Göktürklerin bütün halkıyla Budizmi kabul ederek eski inancı yasakladığını', 'Çin\'in Göktürk Devleti\'ni yönetmeye başladığını', 'Göktürklerin Çin\'le bütün bağlarını kopardığını'], 'Taspar\'ın Budizme ilgisi saray düzeyinde kalmış olsa da Çin ile yalnız savaşın değil kültür alışverişinin de yaşandığını gösterir.'),
  ('Göktürk Devleti\'nin 582\'de ikiye ayrılmasında Çin\'in Sui hanedanının izlediği politika en iyi hangi ifadeyle açıklanır?', 'Göktürk hanedan üyelerini birbirine düşürerek birliği bozmak', ['Göktürklere açıkça savaş ilan edip Ötüken\'i işgal etmek', 'Göktürklerle evlilik yoluyla tek bir devlet kurmak', 'Göktürklerin batı kolunu kendi ordusuna katarak Bizans\'a saldırmak'], 'Sui hanedanı, elçileri aracılığıyla kağanlık adaylarını birbirine karşı kışkırtmış; bu \'böl ve yönet\' siyaseti 582 bölünmesini hızlandırmıştır.'),
  ('Göktürklerde ülkenin hanedan üyelerinin ortak malı sayılması, 582 bölünmesi gibi gelişmeleri nasıl kolaylaştırmıştır?', 'Taht üzerinde hak iddia eden çok sayıda aday ortaya çıkarmıştır', ['Hükümdarın yetkilerini tümüyle meclise devretmesine neden olmuştur', 'Hanedanın taht hakkını yabancı devletlere satmasına yol açmıştır', 'Devlet yönetimini halkın oyuyla seçilen başkana bırakmıştır'], 'Hanedandan her erkeğin yönetme hakkı bulunması, hükümdarın ölümünden sonra kardeşler ve oğullar arasında taht kavgalarına zemin hazırlamıştır.'),
  ('Kürşad ayaklanması başarısız olduğu hâlde Türk tarihinde önemli sayılmasının nedeni aşağıdakilerden hangisidir?', 'Türklerin Çin egemenliğini kabullenmediğini ve bağımsızlık isteğini canlı tuttuğunu göstermesi', ['Göktürk Devleti\'ni hemen yeniden kurup Çin\'i vergiye bağlayarak bağımsızlığı kesin biçimde geri getirmesi', 'Çin\'in başkentini ele geçirerek imparatoru esir alması', 'Türklerin İslamiyet\'e geçişini başlatarak yeni bir dönemi açması'], 'Baskın askerî olarak sonuç vermemiş, ama esaret altındaki Türklerin bağımsızlık iradesini simgeleyen bir olay olarak hatırlanmıştır.'),
  ('Batı Göktürk Devleti\'nin 659\'da yıkılmasının ardından bölgede güçlenen Türk toplulukları arasında aşağıdakilerden hangisi yoktur?', 'Selçuklular', ['Türgişler', 'Karluklar', 'Hazarlar'], 'Batı Göktürk mirası üzerinde Türgiş, Karluk ve Hazar gibi topluluklar güçlenmiştir. Selçuklular ise 11. yüzyılda ortaya çıkmıştır.'),
  ('Kutluk\'un aldığı \'İlteriş\' unvanının anlamı aşağıdakilerden hangisidir?', 'Dağılmış ili (devleti) toplayan, derleyen', ['Gökten kut almış, Tanrı tarafından tahta çıkarılmış hükümdar', 'Batı kanadını yöneten kumandan', 'Düşmanlarını yenen büyük savaşçı'], 'İlteriş, \'ili derleyen\' demektir; Kutluk dağılmış Türk boylarını yeniden bir araya getirdiği için bu unvanı almıştır.'),
  ('Tonyukuk yazıtına göre İlteriş Kutluk\'un ayaklanması başlangıçta küçük bir topluluktan büyüyerek gelişmiştir. Yazıttaki \'on yedi erle çıktı, yetmiş oldu, yedi yüz oldu\' anlatımı neyi gösterir?', 'Ayaklanmanın az sayıda kişiyle başlayıp halk desteğiyle hızla büyüdüğünü', ['Ordunun yalnız yetmiş kişiden oluştuğunu ve hiç büyümediğini', 'Çin\'in ayaklanmaya asker ve silah göndererek baştan destek verdiğini', 'Yazıtın tarih değil yalnızca efsane anlattığını'], 'Bu sayılar, bağımsızlık hareketinin küçük bir çekirdekle başlayıp kısa sürede binlerce kişiyi saran bir harekete dönüştüğünü anlatır.'),
  ('Tonyukuk\'un yazıtında kendisini \'Tabgaç iline kılındım\' diye tanıtması onun hakkında hangi bilgiyi verir?', 'Çin egemenliği döneminde doğup orada yetiştiğini', ['Çin\'e elçi olarak gönderilip ömrünün sonuna kadar orada kaldığını', 'Çin imparatorunun damadı olduğunu', 'Çin\'i fethedip oranın valisi olduğunu'], '\'Kılınmak\' doğmak, yaratılmak anlamındadır; Tonyukuk fetret döneminde Çin egemenliği altında doğup yetiştiğini anlatır.'),
  ('İlteriş Kutluk\'un ölümünden sonra 691\'de tahta geçen, Türk boylarını yeniden derleyip devletin sınırlarını Maveraünnehir\'e kadar genişleten kağan kimdir?', 'Kapgan Kağan', ['Bilge Kağan', 'Taspar Kağan', 'Moyun Çor Kağan'], 'İlteriş\'in kardeşi Kapgan Kağan (691–716) Kırgız, Türgiş ve Karlukları bağlamış, batıda Maveraünnehir\'e kadar seferler düzenlemiştir.'),
  ('Bilge Kağan\'ın şehirler kurmak ve Budist tapınakları yaptırmak istemesine Tonyukuk\'un karşı çıkmasının gerekçesi aşağıdakilerden hangisidir?', 'Az nüfuslu Türklerin surlarla çevrili kentlerde yaşarsa hareket üstünlüğünü yitirip Çin\'e yenileceği', ['Budizmin ticaret gelirlerini azaltacağı ve kervanların uğrak yerlerini değiştirerek hazineyi boşaltacağı', 'Şehir kurmanın Bizans\'ı kızdırarak savaşa yol açacağı', 'Tapınakların yapımı için gerekli taşın bozkırda bulunmayacağı'], 'Tonyukuk, Türk nüfusunun Çin\'e göre çok az olduğunu, göçebe hareketliliğin Türklerin gücü olduğunu, kentlere kapanmanın ise yenilgi getireceğini savunmuştur.'),
  ('Tonyukuk\'un Bilge Kağan\'a verdiği yerleşik hayata geçmeme öğüdü, devletin hangi değerini korumaya yöneliktir?', 'Göçebe hayatın sağladığı askerî hareketlilik ve millî kimlik', ['Çin ile kurulan ticari ortaklığın ve sınır pazarlarının kesintisiz sürdürülmesi', 'Budist rahiplerin devlet yönetimindeki etkisi', 'Hanedan üyelerinin şehirlerde güvenli yaşaması'], 'Tonyukuk\'a göre göçebe yaşam Türklere hem askerî hareket üstünlüğü hem de Çin kültüründe erimeye karşı bir koruma sağlıyordu.'),
  ('Kül Tigin\'in II. Göktürk Devleti\'ndeki asıl görevi ve ünü daha çok hangi alanla ilgilidir?', 'Ordunun başkomutanı olarak kazandığı askerî başarılarla', ['Devletin baş yazıcısı ve tarihçisi olmasıyla', 'Budist rahiplerin başı olarak yürüttüğü dinî görevlerle', 'Çin\'e gönderilen daimî elçi olarak diplomatik başarılarıyla'], 'Kül Tigin, ağabeyi Bilge Kağan döneminde ordunun başında pek çok sefere katılmış bir komutandı; 731\'deki ölümünden sonra adına yazıt dikilmiştir.'),
  ('Orhun yazıtlarının dikilme sırasıyla ilgili olarak aşağıdakilerden hangisi doğrudur?', 'Tonyukuk yazıtı, Kül Tigin ve Bilge Kağan yazıtlarından önce dikilmiştir', ['Bilge Kağan yazıtı Kül Tigin yazıtından önce dikilmiş ilk yazıttır', 'Üç yazıt da Bilge Kağan\'ın ölümünden sonra aynı gün dikilmiştir', 'Kül Tigin yazıtı Tonyukuk\'un ölümünden yüz yıl sonra dikilmiştir'], 'Tonyukuk yazıtı 720\'li yıllarda, Kül Tigin yazıtı 732\'de, Bilge Kağan yazıtı ise 735\'te dikilmiştir.'),
  ('Orhun yazıtlarında Çin\'e ilişkin \'Sözleri tatlı, ipek kumaşları yumuşak\' uyarısıyla Türk milletine anlatılmak istenen nedir?', 'Çin\'in görünüşte cazip yaklaşımlarının Türkleri kendi içinde eritme tehlikesi taşıdığı', ['Çin\'den alınan ipeğin Türk ekonomisinin temelini oluşturduğu', 'Çinlilerin Türklere karşı hiçbir dönemde düşmanca davranmadığı ve güvenilir dost oldukları', 'Türklerin Çin diliyle yazışmayı öğrenmesi gerektiği'], 'Yazıtlar, Çin\'in tatlı sözleri ve değerli armağanlarıyla Türkleri yakına çekip sonra boyun eğdirdiğini anlatarak halkı uyarır.'),
  ('Orhun yazıtlarının tarihî kaynak olarak değeri için aşağıdakilerden hangisi söylenebilir?', 'Türklerin kendi tarihlerini kendi dilleriyle anlattığı ilk büyük metinler arasında olması', ['Çin kaynaklarındaki bütün bilgilerin doğruluğunu kanıtlayan tarafsız belgeler olması', 'Türklerin İslamiyet\'e geçişini ayrıntılı anlatan dinî metinler olması', 'Yalnızca hükümdarların soy ağacını veren kısa mezar taşları olması'], 'Bu yazıtlar, Türk tarihine Türklerin kendi bakışıyla bakılmasını sağlayan, siyasi öğütler ve olaylar içeren uzun anıt metinlerdir.'),
  ('Göktürk alfabesinde ünsüzlerin çoğu için ince ve kalın sıradaki ünlülerle kullanılan ayrı işaretler bulunması, alfabenin hangi dil özelliğine uygun geliştirildiğini gösterir?', 'Türkçedeki büyük ünlü uyumuna', ['Türkçede artikel bulunmasına', 'Türkçede cinsiyet ayrımı yapılmasına', 'Türkçenin sağdan sola konuşulmasına'], 'Kalın ve ince ünlülerle kullanılan ayrı ünsüz işaretleri, Türkçenin ünlü uyumu yapısına uygundur.'),
  ('Göktürk alfabesiyle yazılmış, Yenisey Irmağı havzasında bulunan ve çoğu kısa mezar taşı niteliğindeki yazıtlar daha çok hangi Türk topluluğuna bağlanır?', 'Kırgızlara', ['Hazarlara', 'Peçeneklere', 'Avarlara'], 'Yenisey yazıtları büyük ölçüde Kırgızlara aittir; ölen kişinin ağzından yazılmış kısa ağıt ve mezar metinleridir.'),
  ('Yenisey yazıtlarını Orhun yazıtlarından ayıran en belirgin özellik aşağıdakilerden hangisidir?', 'Çoğunun kısa, kişisel mezar metinleri olması', ['Arap harfleriyle yazılmış olmaları', 'Bizans topraklarında bulunup Grekçe çevirileriyle dikilmiş olmaları', 'Yalnızca Çince yazılmış olmaları'], 'Orhun yazıtları devlet tarihini ve öğütleri anlatan uzun anıtlardır; Yenisey yazıtları ise çoğunlukla ölen kişinin kısa vedasını içerir.'),
  ('Dunhuang\'da bulunan, Göktürk harfleriyle kâğıda yazılmış ve 65 fal içeren eserin adı nedir?', 'Irk Bitig', ['Kutadgu Bilig', 'Altun Yaruk', 'Atabetü\'l-Hakayık'], 'Irk Bitig (Fal Kitabı) Göktürk harfleriyle yazılmış bir fal kitabıdır. Kutadgu Bilig ve Atabetü\'l-Hakayık İslami dönem, Altun Yaruk ise Uygur dönemi eserleridir.'),
  ('Uygur Kağanı Moyun Çor adına dikilen ve Göktürk harfleriyle yazılan yazıt hangisidir?', 'Şine Usu yazıtı', ['Tonyukuk yazıtı', 'Ongin yazıtı', 'Kül Tigin yazıtı'], 'Şine Usu yazıtı Uygur kağanı Moyun Çor\'un faaliyetlerini anlatır ve Uygurların da Göktürk alfabesini kullandığını gösterir.'),
  ('Uygurların ilk döneminde dikilen yazıtlarda Göktürk alfabesinin kullanılması neyi gösterir?', 'Göktürk yazı geleneğinin Uygurlar tarafından da sürdürüldüğünü', ['Uygurların kendilerine ait hiçbir yazı sistemini bilmediğini ve öğrenmediğini', 'Göktürk alfabesinin Uygurlarca icat edildiğini', 'Uygurların Çin alfabesini resmî yazı yaptığını'], 'Uygurlar başlangıçta Göktürk harflerini kullanmış, sonra Soğd kökenli Uygur alfabesine geçmiştir; bu, kültürel sürekliliği gösterir.'),
  ('II. Göktürk Devleti\'ne 8. yüzyılın ortalarında son veren Türk boyları ittifakı aşağıdakilerden hangisidir?', 'Basmil, Uygur ve Karluk', ['Peçenek, Uz ve Kuman boyları', 'Hazar, Bulgar ve Avar', 'Kırgız, Kimek ve Kıpçak'], '742\'de Basmil, Uygur ve Karluklar birleşerek Göktürklere karşı ayaklanmış; kısa sürede Uygurlar bu ittifakın önderi olmuştur.'),
  ('Bilge Kağan\'ın ölümünden sonra II. Göktürk Devleti\'nin hızla zayıflamasında hangi iç etken belirleyici olmuştur?', 'Kağanlar arasında çıkan taht kavgaları ve beylerin çekişmesi', ['Göktürklerin Hristiyanlığı kabul edip boylarla bağlarını koparması', 'Bizans ordusunun Ötüken\'i ele geçirip kağanı esir alması', 'Göktürk halkının tümüyle Avrupa\'ya göç ederek yurdu boşaltması'], 'Bilge Kağan\'dan sonra kısa süre içinde art arda kağan değişmiş, iç çekişmeler bağlı boyların ayaklanmasına zemin hazırlamıştır.'),
  ('Uygur Devleti\'ni 744\'te kuran ve Göktürklerin yerine Ötüken\'e hâkim olan hükümdar kimdir?', 'Kutluk Bilge Kül Kağan', ['Moyun Çor', 'Bögü Kağan', 'İlteriş Kutluk Kağan'], 'Uygur boyunun lideri Kutluk Bilge Kül Kağan, Basmilleri ve Göktürk kalıntılarını yenerek 744\'te Uygur Kağanlığı\'nı kurmuştur.'),
  ('Uygur Kağanlığı\'nın başkenti olan ve Orhun Irmağı kıyısında kurulan şehir hangisidir?', 'Ordu-Balık', ['Balasagun (Kuz Ordu) kenti', 'Beşbalık', 'İtil'], 'Uygurlar Orhun kıyısında Ordu-Balık adlı bir başkent kurmuştur; kalıntıları bugün Karabalgasun olarak bilinir.'),
  ('Kutluk Bilge Kül Kağan\'dan sonra tahta geçen ve devleti sağlamlaştıran Uygur kağanı kimdir?', 'Moyun Çor', ['Bögü Kağan', 'Sulu Kağan', 'Tardu Kağan'], 'Moyun Çor (Bayan Çor) 747–759 arasında hüküm sürmüş, ayaklanmaları bastırıp devleti güçlendirmiştir. Şine Usu yazıtı onun adına dikilmiştir.'),
  ('Çin\'de 755\'te başlayan ve Tang hanedanını çöküşün eşiğine getiren ayaklanma hangisidir?', 'An Lu-şan İsyanı', ['Sarı Sarıklılar İsyanı', 'Boxer (Boksör) İsyanı', 'Taiping İsyanı'], 'Tang ordusunda komutan olan An Lu-şan\'ın 755\'te başlattığı ayaklanma Tang hanedanını ağır biçimde sarsmış, bastırılması için Uygur yardımı istenmiştir.'),
  ('Uygurların An Lu-şan İsyanı\'nın bastırılmasında Tang hanedanına yardım etmesi Uygurlara hangi kazancı sağlamıştır?', 'Çin\'den büyük miktarda ipek ve ayrıcalıklı ticaret hakkı', ['Çin tahtına bir Uygur prensinin oturması', 'Çin\'in bütün kuzey eyaletlerinin kalıcı olarak Uygurlara bırakılması', 'Uygurların Çin\'e vergi ödemekten kurtulması'], 'Yardımlarının karşılığında Uygurlar Çin\'den büyük ölçüde ipek almış ve at-ipek ticaretinde ayrıcalıklı bir konum elde etmiştir.'),
  ('Bögü Kağan\'ın Maniheizmle tanışması hangi olay sırasında gerçekleşmiştir?', 'Tang hanedanına yardım için Çin\'e yaptığı sefer sırasında', ['Bizans\'a gönderdiği elçilik heyetinin getirdiği rahipler aracılığıyla', 'Hindistan\'a düzenlediği akın sırasında', 'İslam ordularıyla yaptığı Talas Savaşı\'nda'], 'Bögü Kağan, An Lu-şan isyancılarına karşı Loyang\'a gittiğinde Soğdlu Mani rahipleriyle tanışmış ve onları Ötüken\'e getirmiştir.'),
  ('Maniheizmin et yemeyi ve hayvan öldürmeyi kısıtlayan öğretileri, savaşçı-göçebe Uygur toplumunu en çok hangi yönden etkilemiştir?', 'Savaşçı ruhun zayıfladığı ve yerleşik hayata yönelişin hızlandığı ileri sürülür', ['Uygurların kısa sürede bütün komşularını fethedip geniş bir imparatorluk kurmasına yol açmıştır', 'Uygurların tümüyle denizciliğe yönelmesine neden olmuştur', 'Uygurların yazıyı bırakıp sözlü kültüre dönmesine yol açmıştır'], 'Hayvancılık ve avcılığa dayalı bir topluluk için bu kısıtlamalar ağırdı; tarihçiler Maniheizmin savaşçı nitelikleri zayıflatıp yerleşik yaşamı kolaylaştırdığını belirtir.'),
  ('Maniheizmin Uygur kültürüne olumlu katkıları arasında aşağıdakilerden hangisi sayılabilir?', 'Yazı, kitap süsleme ve resim sanatının gelişmesi', ['Atlı okçuluğun ve avcılığın Uygur ordusunda yeniden yaygınlaşması', 'Kurgan ve balbal geleneğinin güçlenmesi', 'Göçebe yaşamın kesin biçimde benimsenmesi'], 'Mani dini yazılı kutsal metinlere önem verdiğinden Uygurlarda kitap yazımı, minyatür ve duvar resmi gibi sanatlar gelişmiştir.'),
  ('Maniheizm temel öğretisinde evreni hangi iki ilkenin mücadelesi olarak açıklar?', 'Işık (iyilik) ve karanlık', ['Su ile ateşin ve bunlardan doğan unsurların', 'Yer ve gök', 'Erkek ve dişi'], 'Mani dini, ışık ile karanlığın, yani iyilik ile kötülüğün sürekli mücadelesine dayanan ikici bir inançtır.'),
  ('Uygurların yerleşik hayata geçen ilk Türk topluluklarından biri sayılmasının kanıtları arasında aşağıdakilerden hangisi yer almaz?', 'Ötüken\'i terk edip Avrupa\'ya göç etmeleri', ['Kentler ve kalıcı saraylar kurmaları', 'Tarımla uğraşıp sulama kanalları açarak ürün yetiştirmeleri', 'Tapınak ve manastırlar inşa etmeleri'], 'Kent, tarım ve tapınak yapımı yerleşikliğin göstergeleridir. Uygurlar Avrupa\'ya göç etmemiş, yıkıldıktan sonra Kansu ve Turfan\'a yerleşmiştir.'),
  ('Uygur alfabesinin Moğollar tarafından benimsenmesi Uygurların Orta Asya\'daki kültürel rolü hakkında neyi gösterir?', 'Uygurların bölgede yazı ve bürokrasi geleneğinin taşıyıcısı olduğunu', ['Uygurların Moğolları askerî olarak yendiğini', 'Moğolların kendi dillerini tümüyle bırakıp Türkçeye geçtiğini', 'Uygurların yazıyı Moğollardan öğrendiğini'], 'Uygur kâtipleri ve alfabesi Moğol yönetiminde kullanılmış; bu, Uygurların yerleşik kültür ve yazı birikimini komşularına aktardığını gösterir.'),
  ('Uygurlarla ilgili olarak Dunhuang\'da bulunan ahşaptan oyulmuş tek tek harfler hangi teknolojinin kullanıldığına işaret eder?', 'Hareketli harflerle baskı', ['Su değirmeni', 'Pusula ile yön bulma', 'Barut ile patlayıcı silah üretimi'], 'Dunhuang\'da bulunan Uygurca ahşap harfler, Uygurların hareketli harf baskı tekniğini kullandığını gösterir.'),
  ('Uygurlar döneminden kalan alım-satım, borç ve kira belgelerinde tanıkların adlarının ve mühürlerinin bulunması neyi gösterir?', 'Gelişmiş bir yazılı hukuk ve sözleşme düzeninin varlığını', ['Uygurların ticareti tümüyle yasakladığını', 'Uygurlarda özel mülkiyet kavramının bulunmadığını ve her şeyin kağana ait olduğunu', 'Hukuki işlerin yalnız sözlü yürütüldüğünü'], 'Tanıklı ve mühürlü sözleşmeler, Uygur toplumunda özel mülkiyetin ve yazılı hukuk geleneğinin geliştiğini kanıtlar.'),
  ('Uygur Kağanlığı\'nın 840\'ta yıkılmasında Kırgız saldırısı dışında etkili olan iç nedenler arasında aşağıdakilerden hangisi sayılır?', 'Kıtlık, salgın ve taht kavgaları', ['Bizans\'ın Ötüken\'e yerleşmesi ve Hristiyanlığı yayması', 'Arap ordularının Orhun vadisini fethedip valilik kurması', 'Moğol İmparatorluğu\'nun Uygur topraklarını işgal etmesi'], 'Kaynaklar, Kırgız saldırısından önce Uygur ülkesinde kıtlık, hayvan kırımı, salgın ve iç çekişmeler yaşandığını belirtir. Moğol İmparatorluğu ise yüzyıllar sonra kurulmuştur.'),
  ('Turfan Uygurlarının 1209\'da Moğollara savaşmadan bağlanması, Uygurlara hangi sonucu getirmiştir?', 'Moğol yönetiminde yazı ve bürokrasi alanında etkin rol almalarını', ['Uygur halkının tümüyle sürgün edilmesini', 'Uygur alfabesinin yasaklanıp yerine Arap harflerinin zorunlu kılınmasını', 'Uygurların Avrupa\'ya göç etmek zorunda kalmasını'], 'İdikut\'un gönüllü bağlılığı sonucunda Uygurlar ayrıcalık kazanmış; Uygur kâtipleri ve alfabesi Moğol yönetiminde kullanılmıştır.'),
  ('Kırgızların Hunlar, Göktürkler ve Uygurlar döneminde çoğu zaman bu devletlere bağlı olarak yaşaması, Kırgız tarihinin hangi özelliğini gösterir?', 'Uzun süre büyük bozkır devletlerinin kuzey uç boyu olarak varlık sürdürdüklerini', ['Kırgızların hiçbir dönemde bağımsız bir devlet kuramadığını', 'Kırgızların Hun, Göktürk ve Uygur devletlerini bizzat kendilerinin kurup yönettiğini', 'Kırgızların bu dönemde Avrupa\'da yaşadığını'], 'Kırgızlar Yenisey\'de uzun süre güçlü bozkır devletlerine bağlı kalmış, ancak 840\'ta Uygurları yıkarak kısa süreli bir egemenlik kurmuştur.'),
  ('Batı Göktürk topraklarında 7. yüzyıl sonunda güçlenen ve Yedisu (Yedi Irmak) bölgesinde devlet kuran Türk boyu hangisidir?', 'Türgişler', ['Kırgızlar', 'Tabgaçlar', 'Bulgarlar'], 'Türgişler Batı Göktürk mirası üzerinde, Yedisu bölgesinde 7. yüzyılın sonlarında bağımsız bir devlet kurmuştur.'),
  ('Türgiş Devleti 766\'da hangi Türk topluluğu tarafından ortadan kaldırılmıştır?', 'Karluklar', ['Uygurlar', 'Kırgızlar', 'Oğuzlar'], 'Zayıflayan Türgişlerin topraklarını 766\'da Karluklar ele geçirmiş ve Yedisu bölgesine yerleşmiştir.'),
  ('Karlukların 8. yüzyılda Yedisu bölgesine yerleşmesi ve sonra Karahanlı Devleti\'nin kuruluşunda yer alması, bu boyun Türk tarihindeki rolü için ne söyletir?', 'İslam öncesi bozkır devletlerinden Türk-İslam devletlerine geçişte köprü olduklarını', ['Türk tarihinde hiçbir siyasi rol oynamadıklarını', 'Yalnızca Avrupa\'daki gelişmeleri etkileyip Orta Asya\'da iz bırakmadıklarını', 'Hristiyanlığı Orta Asya\'ya yayan topluluk olduklarını'], 'Karluklar Göktürk ve Uygur dönemlerinde etkin bir boy olmuş, sonra Karahanlı Devleti\'nin kurucu unsurları arasında yer almıştır.'),
  ('Basmil, Uygur ve Karluk ittifakının Göktürkleri yıktıktan kısa süre sonra dağılıp müttefiklerin birbirleriyle savaşması, bozkır siyasetiyle ilgili hangi genellemeyi destekler?', 'Ortak düşmana karşı kurulan ittifakların egemenlik paylaşımında çözülebildiğini', ['Türk boylarının ortak bir düşmana karşı bile kesinlikle ittifak kurmadığını', 'Bozkır siyasetinde ittifakların yüzyıllarca bozulmadan sürdüğünü', 'İttifakların yalnız din birliğine dayandığını'], 'Göktürkler yıkılınca kağanlık için rekabet başlamış; Uygurlar önce Basmilleri, sonra Karlukları bölgeden uzaklaştırmıştır.'),
  ('Türk tarihçilerinin çoğunluğuna göre \'kağan\' unvanını hükümdar unvanı olarak ilk kullanan topluluk hangisidir?', 'Asya Avarları (Juan-juanlar)', ['Göktürkler (Kök Türk Kağanlığı)', 'Uygurlar', 'Hazarlar'], 'Juan-juan hükümdarı 5. yüzyıl başında \'kağan\' unvanını kullanmış; bu unvan daha sonra Göktürkler aracılığıyla Türk dünyasında yaygınlaşmıştır.'),
  ('Asya Avarlarının (Juan-juanların) 552\'de Göktürklere yenilmesinin ardından bir kısmının batıya göç etmesi hangi gelişmeyle sonuçlanmıştır?', 'Orta Avrupa\'da Avrupa Avar Kağanlığı\'nın kurulmasıyla', ['Hindistan\'da Ak Hun Devleti\'nin kurulmasıyla', 'Çin\'de Tang hanedanının kurulmasıyla', 'Anadolu\'da ilk Türk beyliklerinin kurulup Bizans sınırına yerleşilmesiyle'], 'Batıya giden Avarlar 6. yüzyılın ortalarında Karadeniz\'in kuzeyine, ardından Macaristan ovasına gelerek Avrupa Avar Kağanlığı\'nı kurmuştur.'),
  ('Gepidlerin yıkılmasından sonra Langobardların 568\'de İtalya\'ya göç etmesi, Avarlara hangi imkânı sağlamıştır?', 'Macaristan ovasının tamamına rakipsiz yerleşme imkânı', ['İtalya\'yı savaşmadan ele geçirme imkânı', 'Bizans\'ın başkentini kendi merkezleri yapma imkânı', 'Kuzey Afrika\'ya geçerek Kartaca ve çevresindeki kıyı kentlerini alma imkânı'], 'Langobardların İtalya\'ya gitmesiyle Pannonia\'da Avarlara rakip kalmamış; Avar Kağanlığı\'nın merkezi burası olmuştur.'),
  ('Avrupa Avarlarının ünlü bozkır tipi koşum takımlarından biri olan ve Avrupa\'ya onların aracılığıyla yayıldığı düşünülen ekipman hangisidir?', 'Üzengi', ['Pusula', 'Barut', 'Yel değirmeni'], 'Demir üzengi Avarlarla birlikte Avrupa\'da yaygınlaşmış; Bizans askerî eserleri de Avar teçhizatının örnek alınmasını önermiştir.'),
  ('626\'da İstanbul\'u Sasanilerle iş birliği hâlinde kuşatan, ancak şehri alamayan bozkır kökenli topluluk hangisidir?', 'Avarlar', ['Hunlar', 'Peçenekler', 'Uzlar'], '626\'da Avarlar karadan, Sasaniler Boğaz\'ın Asya yakasından İstanbul\'u kuşatmış; Bizans donanmasının iki müttefiki ayırması üzerine kuşatma başarısız olmuştur.'),
  ('626 İstanbul kuşatmasının başarısız olmasında aşağıdakilerden hangisi belirleyici olmuştur?', 'Bizans donanmasının Avarlarla Sasanilerin Boğaz\'da birleşmesini engellemesi', ['Avarların kuşatmaya hiç katılmayıp geri dönmesi', 'Sasanilerin kenti aldıktan sonra Avarlara teslim etmeyip kendi valilerini ataması', 'Hunların kuşatmayı kaldırmak için Bizans\'a yardım etmesi'], 'Boğaz\'ın iki yakasındaki müttefikler denizde üstün olan Bizans donanması yüzünden ortak saldırı yapamamış, kuşatma dağılmıştır.'),
  ('626 kuşatmasının başarısızlığı Avrupa Avar Kağanlığı\'nı nasıl etkilemiştir?', 'Kağanın saygınlığı sarsılmış, bağlı Slav ve Bulgar toplulukları ayaklanmıştır', ['Avarlar İstanbul\'u kısa süre sonra ikinci bir saldırıyla ele geçirmiştir', 'Avarlar Bizans\'la birleşerek tek ve güçlü bir imparatorluk kurmuştur', 'Avarların yönetimi Sasani hükümdarına geçmiştir'], 'Başarısızlık sonrası Avar kağanının otoritesi zayıflamış; Slavlar ve Kubrat önderliğindeki Bulgarlar Avar egemenliğinden ayrılmıştır.'),
  ('Avrupa Avar Kağanlığı\'na 8. yüzyılın sonlarında ağır darbe vurup hazinesini ele geçiren hükümdar kimdir?', 'Şarlman (Büyük Karl)', ['II. Justinianus', 'I. Leo (Bizans imparatoru)', 'Odoakr'], 'Frank kralı Şarlman 790\'larda Avarlara karşı seferler düzenlemiş, Avarların surlarla çevrili merkezini ve hazinesini ele geçirmiştir.'),
  ('Göktürklerin Bizans\'a gönderdiği elçilerin, Bizans\'ın batıya kaçan Avarlara sığınak vermesinden yakınması hangi durumu yansıtır?', 'Göktürklerin Avarları kendi egemenliğinden kaçmış uyruklar olarak görmesini', ['Göktürklerin Avarlarla birleşip Bizans\'a saldırmayı planladığını', 'Bizans\'ın Göktürkleri Avarlara karşı korumak istediğini', 'Avarların Göktürk kağanını kendi aralarından seçme hakkına sahip olduğunu'], 'Göktürkler, kendilerinden kaçan Avarları kaçak uyruk saymış ve Bizans\'tan onları korumamasını istemiştir; bu, bozkırda egemenlik anlayışını gösterir.'),
  ('Avrupa Avar Kağanlığı\'nın merkezinin bulunduğu bölge, daha önce hangi Türk devletinin de merkezi olmuştur?', 'Avrupa Hun Devleti', ['Hazar Kağanlığı', 'Uygur Kağanlığı', 'Tuna Bulgar Devleti'], 'Macaristan ovası (Pannonia) hem Attila\'nın Hun Devleti\'nin hem de daha sonra Avar Kağanlığı\'nın merkezi olmuştur.'),
  ('Avrupa Avarlarının Bizans\'tan düzenli vergi alması ve Balkanlara akınlar yapması, onların hangi önceki Türk devletiyle benzer bir politika izlediğini gösterir?', 'Avrupa Hunları', ['Uygurlar', 'Kırgızlar', 'Kansu Uygurları'], 'Avrupa Hunları da Bizans\'ı vergiye bağlamış ve Balkanlara akınlar düzenlemiştir; Avarlar benzer bir bozkır politikası izlemiştir.'),
  ('Avrupa Avarlarının mezarlarında sık rastlanan kemer tokası ve süs levhalarındaki hayvan ve bitki motifleri hangi kültürel bağı gösterir?', 'Orta Asya bozkır sanatı geleneğiyle süreklilik', ['Antik Mısır mimari ve tapınak süsleme geleneğiyle süreklilik', 'Roma\'nın mermer heykel sanatıyla süreklilik', 'Arap hat sanatı geleneğiyle süreklilik'], 'Avar maden işçiliğindeki motifler, Orta Asya\'daki bozkır hayvan üslubuyla bağlantılı bir sanat geleneğini yansıtır.'),
  ('Hazar Kağanlığı 7. yüzyılda hangi devletin batı kanadının zayıflamasından sonra bağımsızlık kazanarak güçlenmiştir?', 'Batı Göktürk Devleti', ['Avrupa Hun Devleti\'nin doğu kolu', 'Uygur Kağanlığı', 'Tuna Bulgar Devleti'], 'Hazarlar Batı Göktürk egemenliğinin dağılmasıyla Kuzey Kafkasya ve aşağı İdil bölgesinde bağımsız bir kağanlık kurmuştur.'),
  ('Hazar Kağanlığı\'nın en uzun süre başkentlik yapan, İdil Nehri\'nin denize döküldüğü yerde kurulmuş kenti hangisidir?', 'İtil', ['Ordu-Balık', 'Sarkel', 'Suyab'], 'Hazarlar başkentlerini önce Belencer ve Semender\'de kurmuş, sonra İdil deltasındaki İtil\'i başkent yapmıştır. Sarkel ise Don kıyısındaki bir kaledir.'),
  ('Hazar yönetimindeki kağan-bek ikiliği, eski Türk devlet geleneğindeki hangi uygulamayla karşılaştırıldığında farklıdır?', 'Paylaşımın coğrafi kanatlara göre değil, sembolik ve yürütme yetkisine göre yapılması', ['Hükümdarın kurultayca seçilmesini tamamen kaldırıp mutlak ve babadan oğula geçen bir krallık kurması', 'Ülkenin hanedan üyelerinin ortak malı sayılmasını yasaklaması', 'Ordunun onlu sisteme göre düzenlenmesine son vermesi'], 'Göktürklerde doğu ve batı kanatları coğrafi olarak paylaşılırdı. Hazarlarda ise sembolik-dinî otorite kağanda, yürütme ve komuta bekte toplanmıştı.'),
  ('Arap tarihçi Mesudi\'nin aktardığına göre Hazar başkentinde Müslüman, Hristiyan, Yahudi ve putperest topluluklar için ayrı yargıçlar bulunması Hazar devletinin hangi özelliğini gösterir?', 'Dinî hoşgörü ve çok dinli bir toplum düzeni', ['Tek bir resmî dinin zorla yayılması', 'Yargı yetkisinin yalnız kağanda toplanıp başka hiçbir yargıca bırakılmaması', 'Hukuk düzeninin hiç bulunmaması'], 'Her topluluğun kendi hukukuna göre yargılanması, Hazarların farklı dinlere karşı hoşgörülü ve çoğulcu bir yönetim uyguladığını gösterir.'),
  ('Hazar yöneticilerinin Hristiyanlık ya da İslam yerine Museviliği benimsemesi, dönemin dengeleri açısından nasıl yorumlanır?', 'Bizans ve Arap Halifeliği arasında iki gücün de dinî etkisinden uzak kalma isteği', ['Bizans\'a tümüyle bağlanıp onun eyaleti olma isteği', 'Arap Halifeliği\'ne katılarak halifenin ordusuna düzenli asker verme isteği', 'Çin ile birleşip Budist bir imparatorluk kurma isteği'], 'Hristiyanlık Bizans\'ın, İslam ise Halifeliğin dinîydi; Hazarların Museviliği seçmesi iki büyük komşudan da bağımsızlığını koruma çabası olarak yorumlanır.'),
  ('Hazar Kağanlığı\'nın ekonomik gücünün temel kaynağı aşağıdakilerden hangisidir?', 'Topraklarından geçen ticaret yollarından alınan gümrük vergileri', ['Geniş deniz filosuyla yapılan korsanlık', 'Altın ve gümüş madenlerinin işletilip uzak ülkelere ihraç edilmesi', 'Pirinç tarımı ve ihracatı'], 'Hazarlar İdil ve Kafkas yollarıyla kuzeyden gelen kürk ve köle, güneyden gelen ipek ve gümüş ticaretini denetleyip geçen mallardan vergi almıştır.'),
  ('Hazarların 7. ve 8. yüzyıllarda Kafkasya\'da Araplarla yaptığı uzun savaşların Doğu Avrupa tarihi açısından sonucu ne olmuştur?', 'Arap ilerleyişinin Kafkasların kuzeyine yayılması büyük ölçüde durdurulmuştur', ['Arap orduları İdil boyunu fethedip Kiev\'e ulaşmıştır', 'Hazar Kağanlığı Arap halifeliğine katılarak bir eyalet hâline gelmiştir', 'Hazarlar Bağdat\'ı ele geçirip halifeliği yıkmıştır'], 'Hazar-Arap savaşlarında Hazarlar Kafkas geçitlerini korumuş, İslam ordularının Doğu Avrupa bozkırlarına doğru ilerlemesini önlemiştir.'),
  ('Hazar hanedanıyla Bizans sarayı arasında evlilikler yapılması, iki devlet ilişkileri hakkında neyi gösterir?', 'Ortak düşmanlara karşı uzun süreli bir ittifak kurulduğunu', ['Hazarların Bizans\'a vergi ödeyen bir eyalet olduğunu', 'Bizans\'ın Hazarları Hristiyanlaştırmayı başardığını', 'İki devletin sürekli savaş hâlinde olduğunu ve barışın hiç sağlanamadığını'], 'Evlilikler, Sasanilere ve Araplara karşı kurulan Bizans-Hazar ittifakını pekiştiren diplomatik bağlardı.'),
  ('Hazarların Don Nehri kıyısında Bizanslı mühendislerin yardımıyla inşa ettirdiği kalenin adı nedir?', 'Sarkel', ['Semender', 'Sirmium', 'Bulgar'], 'Sarkel (Ak Ev), 9. yüzyılda Bizans\'ın teknik desteğiyle Don kıyısında yapılmış bir Hazar kalesidir.'),
  ('Hazar Kağanlığı\'nı 960\'larda yaptığı seferlerle çöküşe sürükleyen ve Sarkel ile İtil\'i ele geçiren güç hangisidir?', 'Kiev Knezliği', ['Bizans İmparatorluğu', 'Abbasi Halifeliği ve Horasan valileri', 'Uygur Kağanlığı'], 'Kiev prensi Svyatoslav 960\'larda Sarkel\'i ve başkent İtil\'i almış, bu darbeden sonra Hazar Kağanlığı bir daha toparlanamamıştır.'),
  ('Hazar Kağanlığı\'nın Kiev Rus Knezliği karşısında zayıflaması Doğu Avrupa\'da hangi gelişmeyi kolaylaştırmıştır?', 'Rusların İdil ve Karadeniz yönünde güçlenmesini', ['Avarların yeniden Pannonia\'da devlet kurmasını', 'Hunların Avrupa\'ya ikinci kez girerek Pannonia\'da yeniden devlet kurmasını', 'Uygurların batıya göç etmesini'], 'Hazarların çöküşüyle Kiev Rusları bozkırdaki ticaret yollarına daha fazla yayılmış ve bölgede etkin bir güç hâline gelmiştir.'),
  ('Hazar Kağanlığı ile İdil Bulgarları arasındaki ilişkinin genel niteliği aşağıdakilerden hangisidir?', 'İdil Bulgarlarının uzun süre Hazarlara bağlı ve vergi verir durumda olması', ['Hazarların İdil Bulgarlarına vergi ödemesi', 'İki devletin uzun süre aynı kağan tarafından ortaklaşa yönetilmesi', 'Hazarların İdil Bulgarlarını İslam\'a geçirmesi'], 'İdil Bulgarları 10. yüzyıla kadar Hazar Kağanlığı\'na bağlıydı; Hazar baskısından kurtulma isteği onları Abbasilerle yakınlaşmaya itmiştir.'),
  ('7. yüzyılın ilk yarısında Avar egemenliğinden kurtularak Azak Denizi ve Kuban çevresinde \'Büyük Bulgarya\' adıyla bir devlet kuran hükümdar kimdir?', 'Kubrat Han', ['Asparuh Han', 'Krum Han', 'Bayan Kağan'], 'Kubrat Han, Avarlara karşı ayaklanıp Karadeniz\'in kuzeyinde Büyük Bulgarya\'yı kurmuş ve Bizans imparatoru Herakleios ile dostluk ilişkisi geliştirmiştir.'),
  ('Kubrat Han\'ın ölümünden sonra Büyük Bulgarya\'nın dağılmasında dış etken olarak hangi devletin baskısı belirleyici olmuştur?', 'Hazar Kağanlığı', ['Abbasi Halifeliği\'nin Kafkas valileri', 'Frank Krallığı', 'Uygur Kağanlığı'], 'Kubrat\'ın oğulları arasındaki ayrılık, doğudan ilerleyen Hazarların baskısıyla birleşince Bulgar boyları farklı yönlere göç etmiştir.'),
  ('Kubrat Han\'ın oğullarının farklı yönlere giderek ayrı devletler kurması, Bulgar tarihinde aşağıdaki sonuçlardan hangisine yol açmıştır?', 'Biri Balkanlarda, biri İdil boyunda iki ayrı Bulgar devletinin ortaya çıkmasına', ['Bütün Bulgar boylarının tek bir devlet altında Kafkasya\'nın kuzeyinde yeniden toplanmasına', 'Bulgarların tümüyle Hazarlara karışıp tarihten silinmesine', 'Bulgarların Çin\'e göç ederek orada hanedan kurmasına'], 'Asparuh\'un kolu Tuna Bulgar Devleti\'ni, kuzeye giden kol ise İdil Bulgar Devleti\'ni kurmuştur; böylece Bulgar adı iki ayrı coğrafyada yaşamıştır.'),
  ('Bizans\'ın 681\'de Asparuh\'un devletini tanıyıp yıllık vergi ödemeyi kabul etmesi Tuna Bulgarları için ne anlama gelir?', 'Balkanlarda Bizans\'ın tanıdığı bağımsız bir devlet hâline gelmeleri', ['Bizans\'ın bir eyaleti olarak yönetilmeye başlamaları', 'Hristiyanlığı resmen kabul edip Bizans kilisesine bağlanmak zorunda kalmaları', 'Avarlara bağlı bir beylik olarak kalmaları'], '681 antlaşmasıyla Bizans, Tuna Bulgar Devleti\'ni hukuken tanımış; bu tarih Bulgaristan\'ın kuruluş tarihi olarak kabul edilir.'),
  ('811\'de Bizans imparatoru I. Nikephoros\'u yenip öldüren ve kafatasından kadeh yaptırdığı anlatılan Tuna Bulgar hükümdarı kimdir?', 'Krum Han', ['Asparuh Han', 'Tervel Han', 'Boris Han'], 'Krum Han, Bulgar başkenti Pliska\'yı yağmalayan I. Nikephoros\'u dönüş yolunda pusuya düşürüp yenmiş ve imparatoru öldürmüştür.'),
  ('Tuna Bulgar Devleti\'nin ilk başkenti olan kent hangisidir?', 'Pliska', ['Sarkel', 'Kiev', 'Sirmium'], 'Asparuh\'un kurduğu devletin ilk merkezi Pliska\'dır; daha sonra başkent Preslav\'a taşınmıştır.'),
  ('Tuna Bulgarlarında 864–865 yıllarında Hristiyanlığı resmî din olarak kabul eden hükümdar kimdir?', 'Boris', ['Krum', 'Omurtag', 'Kubrat'], 'Han Boris, Bizans\'ın etkisiyle Hristiyanlığı kabul etmiş ve vaftiz adı olarak Mihail\'i almıştır.'),
  ('Tuna Bulgarlarının zamanla Slavlaşmasında aşağıdakilerden hangisinin etkisi en azdır?', 'Orta Asya\'dan sürekli yeni Bulgar boylarının gelmesi', ['Sayıca az olup kalabalık Slav nüfusu arasında yaşamaları', 'Hristiyanlığı kabul ederek Slav kilise dilini benimsemeleri', 'Slavlarla evlilik yoluyla kaynaşmaları'], 'Slavlaşmanın nedenleri azınlıkta kalmak, Hristiyanlık ve Slav kilise dili ile karışık evliliklerdir. Orta Asya\'dan yeni boyların gelmesi tam tersine Türk unsurunu güçlendirirdi.'),
  ('Tuna Bulgarlarının Hristiyanlığı kabul etmesinin ardından Slav kilise dilinin devlet ve dinde yaygınlaşması hangi sonucu doğurmuştur?', 'Bulgar Türklerinin dil ve kimlik bakımından Slav çoğunluk içinde erimesi', ['Türkçenin Balkanlarda resmî dil olarak güçlenmesi', 'Bulgarların Müslümanlığa geçip Abbasi halifesine elçi göndermesi', 'Bulgar Devleti\'nin Hazarlara bağlanması'], 'Kilise ve yazı dilinin Slavca olması, zaten azınlıkta olan Türk kökenli Bulgarların kısa sürede Slavlaşmasını hızlandırmıştır.'),
  ('Bulgar adının Türkçe \'bulgamak\' (karıştırmak) kökünden geldiği görüşü, bu topluluğun oluşumu hakkında neyi ima eder?', 'Farklı boyların birleşip karışmasıyla meydana geldiklerini', ['Tek bir aileden türeyip başka hiçbir boyla karışmadan çoğaldıklarını', 'Türkçeyi hiç bilmediklerini', 'Ana yurtlarının Balkanlar olduğunu'], 'Ad, Hun kalıntılarıyla Ogur boylarının karışmasından oluşan bir boy birliğini anlatır şeklinde yorumlanır.'),
  ('Kubrat Han\'ın Bizans imparatoru Herakleios ile dostluk kurması, onun hangi stratejik amacına hizmet etmiştir?', 'Avarlara karşı güçlü bir müttefik edinmeye', ['Bizans\'ı fethedip İstanbul\'u başkent yapmaya', 'Hazarlarla birleşip Bizans\'a savaş açmaya', 'Bulgarları İslam\'a geçirmeye'], 'Kubrat, Avar egemenliğinden kurtulmak için Bizans\'ın desteğini almış; Avarlar Bizans\'ın da düşmanı olduğundan çıkarlar örtüşmüştür.'),
  ('9. yüzyılın sonlarında Peçeneklerin İdil-Yayık bölgesinden batıya göç etmesinde hangi toplulukların baskısı etkili olmuştur?', 'Oğuzlar (Uzlar) ve Hazarlar', ['Araplar ve Bizans İmparatorluğu', 'Franklar ve Langobardlar', 'Tibetliler ve Çinliler'], 'Doğudan Oğuzların, güneyden Hazarların sıkıştırması üzerine Peçenekler batıya, Karadeniz\'in kuzeyine doğru göç etmiştir.'),
  ('Peçeneklerin 9. yüzyılın sonunda Karadeniz\'in kuzeyine gelmesi, o bölgede yaşayan hangi topluluğun batıya göç edip Pannonia\'ya yerleşmesine yol açmıştır?', 'Macarlar', ['Ostrogotlar', 'Avarlar', 'Langobardlar'], 'Peçeneklerin baskısıyla Etelköz\'deki Macarlar 890\'larda Karpatları aşarak bugünkü Macaristan ovasına yerleşmiştir.'),
  ('Bizans\'ın 10. yüzyılda Peçeneklerle dostluk kurmaya özel önem vermesinin temel nedeni aşağıdakilerden hangisidir?', 'Onları Ruslara ve Bulgarlara karşı bir denge unsuru olarak kullanmak', ['Peçeneklerden donanma kurmak için gemici ve kürekçi almak', 'Peçenekleri Hristiyanlaştırıp Anadolu\'ya yerleştirmek', 'Peçeneklerin İstanbul\'u Araplara karşı savunmasını istemek'], 'Bizans, kuzey sınırındaki Rus ve Bulgar tehditlerini dengelemek için Peçeneklere hediyeler verip onları müttefik olarak tutmaya çalışmıştır.'),
  ('Bağımsızlıklarını yitiren Peçeneklerin bir bölümünün sonraki dönemde Bizans ve Macar topraklarında yaşaması, hangi süreci başlatmıştır?', 'Bu toplulukların yerli halklar arasında zamanla erimesini', ['Peçeneklerin Bizans tahtına geçmesini', 'Macaristan\'da bağımsız bir Peçenek kağanlığı kurulmasını', 'Peçeneklerin Orta Asya\'ya geri dönmesini'], 'Bizans ve Macaristan\'a yerleştirilen Peçenekler orduya ve köylere dağıtılmış, zamanla Hristiyanlaşarak yerli halklara karışmıştır.'),
  ('Oğuz Yabgu Devleti\'nin merkezi olan ve Seyhun Nehri\'nin aşağı kesiminde bulunan şehir hangisidir?', 'Yenikent', ['Kaşgar', 'Beşbalık', 'Suyab'], 'Oğuz Yabgu Devleti\'nin merkezi Seyhun\'un aşağı kısmındaki Yenikent\'tir; Selçuk Bey\'in yerleştiği Cend de bu bölgededir.'),
  ('Bizans kaynaklarında \'Uz\' olarak anılan Oğuz topluluklarının 1064\'te Tuna\'yı geçip Balkanlara girmesinin ardından yaşadıkları için aşağıdakilerden hangisi doğrudur?', 'Salgın ve soğukla büyük kayıplar verip dağılmışlar, kalanları Bizans hizmetine girmiştir', ['Bizans\'ı yıkarak İstanbul\'da bir Uz devleti kurmuşlardır', 'Macaristan\'ı fethederek orada kalıcı bir devlet kurmuşlardır', 'Toplu olarak Orta Asya\'ya geri dönüp Seyhun boyunda yeniden devlet kurmuşlardır'], 'Balkanlara giren Uzlar salgın, kıtlık ve Bizans-Bulgar saldırılarıyla ağır kayıp vermiş; kalanlar Bizans ordusuna paralı asker olarak alınmıştır.'),
  ('Aynı Türk topluluğunun Bizans kaynaklarında \'Kuman\', Rus yıllıklarında \'Polovets\' ve Macar kaynaklarında \'Kun\' olarak geçmesi neyi gösterir?', 'Bu topluluğun çok geniş bir coğrafyada pek çok halkla temas kurduğunu', ['Bu adların üç ayrı ve birbirinden habersiz topluluğu anlattığını', 'Topluluğun kendine ait bir adı bulunmadığını', 'Bu kaynakların tek bir yazarın kaleminden çıktığını ve birbirini kopyaladığını'], 'Farklı dillerdeki adlar, Kuman-Kıpçakların Bizans\'tan Rus knezliklerine ve Macaristan\'a kadar geniş bir alanda etkili olduğunu yansıtır.'),
  ('Gürcü kralı IV. David\'in 12. yüzyılda binlerce Kıpçak ailesini ülkesine yerleştirmesinin temel amacı nedir?', 'Güçlü bir orduya kavuşup Selçuklulara karşı direnmek', ['Gürcistan\'ı Kıpçaklara bırakıp başka ülkeye göç etmek', 'Kıpçakları köle olarak Bizans\'a satmak', 'Kıpçak dilini Gürcistan\'da resmî dil yapmak'], 'IV. David Kıpçaklarla akrabalık kurup çok sayıda Kıpçak savaşçıyı ailesiyle birlikte getirmiş ve bu güçle Selçuklulara karşı başarılar kazanmıştır.'),
  ('6. yüzyılda Kuzey Kafkasya\'da yaşayan ve Bizans ile Sasaniler arasındaki savaşlarda kimi zaman bir tarafa kimi zaman öbür tarafa asker veren Türk topluluğu hangisidir?', 'Sabirler', ['Kırgızlar', 'Tabgaçlar', 'Basmiller'], 'Kuzey Kafkasya\'daki Sabirler, iki büyük imparatorluk arasındaki savaşlarda paralı asker olarak taraf değiştirebilen güçlü bir topluluktu.'),
  ('Bizans\'ın Karadeniz\'in kuzeyindeki Kutrigurlar ile Utrigurları birbirine karşı kışkırtması hangi diplomatik yöntemin örneğidir?', 'Rakip toplulukları birbirine düşürerek zayıflatma', ['Evlilik yoluyla tek bir hanedan kurma', 'Ticaret ambargosu uygulayarak toplulukları açlıkla teslim alma', 'Toprak satın alarak barış sağlama'], 'Bizans, kuzeydeki tehlikeli toplulukları altın ve vaatlerle birbirine karşı kullanarak kendi sınırlarını korumaya çalışmıştır.'),
  ('Kut anlayışının yalnız hanedan soyuna bağlı olması aşağıdakilerden hangisini engellemiştir?', 'Hanedan dışından birinin meşru hükümdar sayılmasını', ['Hükümdarın kurultay toplamasını', 'Kağanın savaşlara bizzat katılıp orduya komuta etmesini', 'Hükümdarın vergi toplamasını'], 'Kutun belirli bir aileye verildiğine inanıldığından, hanedan dışındaki güçlü beylerin kağan olması meşru görülmezdi.'),
  ('Eski Türk devletlerinde kağanın da töre kurallarına uymak zorunda olması aşağıdaki kavramlardan hangisine yakın bir anlayışı yansıtır?', 'Hukukun üstünlüğü', ['Teokrasi', 'Mutlak monarşi', 'Feodalite'], 'Kağanın töreyle bağlı sayılması, yöneticinin keyfî davranamayacağını ve hukukun herkes için geçerli olduğunu gösterir.'),
  ('Eski Türk devletlerinde hükümdarın eşi olan hatunun konumuna ilişkin aşağıdakilerden hangisi söylenemez?', 'Devlet işlerine katılması kesin olarak yasaklanmıştı', ['Kurultay toplantılarına katılıp görüş bildirebilirdi', 'Yabancı elçileri kağanla birlikte kabul edebilirdi', 'Kendi ordugâhına ve gelirlerine sahip olabilirdi'], 'Hatunlar kurultaylara katılmış, elçi kabullerinde bulunmuş ve yönetimde söz sahibi olmuştur. Devlet işlerinden dışlandıkları söylenemez.'),
  ('Göktürklerde \'tigin\' unvanı kimler için kullanılırdı?', 'Hanedan ailesinden olan erkek çocuklar (prensler) için', ['Yabancı halkların başına atanan ve vergi toplayan valiler için', 'Dinî törenleri yöneten kamlar için', 'Kağanın danışmanı olan vezirler için'], 'Tigin, kağan soyundan gelen prenslerin unvanıdır; Kül Tigin adında da bu unvan yer alır.'),
  ('Tonyukuk\'un yazıtlarda taşıdığı \'Ayguçı\' unvanı devlet yönetimindeki hangi göreve karşılık gelir?', 'Kağanın danışmanı, veziri', ['Ordunun öncü birliğinin komutanı', 'Hazineyi koruyan saray bekçisi', 'Elçilik heyetinin tercümanı'], 'Ayguçı, kağana öğüt veren ve devlet işlerinde ona yardım eden en yüksek danışmanlık makamıdır.'),
  ('İkili teşkilatın uzun vadede doğurabildiği olumsuz sonuç aşağıdakilerden hangisidir?', 'Kanatların zamanla ayrı devletlere dönüşmesi', ['Ordunun onlu sisteme göre düzenlenememesi ve dağınık kalması', 'Kurultayın toplanmasının imkânsızlaşması', 'Hükümdarın kut inancını yitirmesi'], 'Batı kanadındaki yabgular güçlendikçe bağımsızlık eğilimine girmiş; Göktürklerin 582\'de Doğu ve Batı olarak ayrılması bunun örneğidir.'),
  ('Bir öğrenci ikili teşkilat ile Avrupa\'daki feodal düzeni karşılaştırıyor. Aşağıdakilerden hangisi ikili teşkilatı feodaliteden ayıran özelliktir?', 'Yönetimin hanedan üyeleri arasında paylaşılması ve kanatların kağana bağlı kalması', ['Toprağın soylular arasında küçük parçalara bölünüp her birinin kendi ordusunu kurması', 'Köylülerin toprağa bağlı serf olması', 'Şatoların siyasi gücün merkezi olması'], 'Feodalitede güç çok sayıda soylu arasında parçalanır. İkili teşkilatta ise yönetim hanedan içinde iki kanada bölünür ve batı kanadı doğudaki kağanı üstün tanır.'),
  ('Bozkır ordularının en çok zorlandığı savaş türü aşağıdakilerden hangisidir?', 'Surlarla korunan kentlerin uzun süreli kuşatması', ['Açık ovada yapılan meydan savaşları', 'Düşmanı pusuya düşürmeye dayanan ani baskınlar ve gece saldırıları', 'Hızlı akınlar ve geri çekilmeler'], 'Atlı birlikler açık alanda üstündü; ancak kuşatma araçları ve uzun süreli ikmal gerektiren sur kuşatmaları onlar için zordu.'),
  ('Eski Türklerde örgütlü bir din adamları sınıfının bulunmaması, toplum yapısı açısından hangi sonucu doğurmuştur?', 'Dinî bir zümrenin devlet yönetimi üzerinde baskı kuramaması', ['Kağanın dinî törenlere hiç katılmaması', 'Halkın hiçbir inanca sahip olmaması', 'Devletin rahipler tarafından yönetilip kağanın onlara bağlı olması'], 'Mısır ya da Sümer\'deki gibi güçlü bir rahip sınıfı oluşmadığından devlet yönetiminde dinî bir zümrenin belirleyici olması söz konusu olmamıştır.'),
  ('Ergenekon Destanı\'nda vadiden çıkışta yol gösteren bozkurt ve demir dağın eritilmesi motifleri, Göktürk toplumu hakkında hangi çıkarımı destekler?', 'Demircilik ve kurt simgesinin Göktürk kimliğinde önemli yer tuttuğunu', ['Göktürklerin denizcilikle geçindiğini', 'Göktürklerin hayvanları kutsal saymayıp onları yalnız besin olarak gördüğünü', 'Göktürklerin madenciliği bilmediğini'], 'Göktürklerin Juan-juanlara demircilik yaptığı bilinir; kurt da onların türeyiş efsanesinde ata simgesidir. Destan bu iki unsuru birleştirir.'),
  ('Uygur türeyiş efsanesinde bir Hun hükümdarının kızlarını yüksek bir kuleye koymasının amacı nedir?', 'Kızlarını Tanrı ile evlendirmek', ['Onları düşmandan saklamak', 'Onlara yıldızları gözlemeyi öğretmek', 'Onları kurban etmek'], 'Efsaneye göre hükümdar, güzelliklerinden dolayı kızlarının ancak Tanrı\'ya layık olduğunu düşünmüş; sonunda küçük kız kuleye gelen bir kurtla evlenmiş ve Uygurlar ondan türemiştir.'),
  ('Kaşgarlı Mahmut\'un eserinde Alp Er Tonga\'nın ölümü üzerine söylenmiş bir ağıtın (sagu) bulunması bu destan hakkında neyi gösterir?', 'Destanın yüzyıllar boyunca halk arasında sözlü olarak yaşadığını', ['Destanın bütünüyle Kaşgarlı Mahmut tarafından uydurulup ilk kez onun eserinde ortaya çıktığını', 'Alp Er Tonga\'nın 11. yüzyılda yaşadığını', 'Destanın ilk kez Arapça yazıldığını'], 'Çok eski bir kahraman için 11. yüzyılda hâlâ ağıt bilinmesi, destanın sözlü gelenekte kuşaktan kuşağa aktarıldığını gösterir.'),
  ('Bir tarihçi İslamiyet öncesi Türk destanlarını tarihî kaynak olarak kullanırken nasıl bir yol izlemelidir?', 'Destanlardaki bilgileri yazıt ve yabancı kaynaklarla karşılaştırarak değerlendirmelidir', ['Destanlardaki her bilgiyi kesin tarihî olgu saymalıdır', 'Destanları tarihle hiçbir ilgisi olmayan masallar sayıp araştırmalarında tümüyle dışlamalıdır', 'Yalnızca destanlardaki sayıları dikkate almalıdır'], 'Destanlar toplumun değerlerini ve hafızasını yansıtır, ancak olağanüstü unsurlar da içerir; bu nedenle başka kaynaklarla karşılaştırılarak kullanılmalıdır.'),
  ('Aşağıdaki olaylar eskiden yeniye doğru sıralandığında üçüncü sırada hangisi yer alır? I. Uygurların yıkılması II. Katalon Ovası Savaşı III. Göktürklerin 582\'de ikiye ayrılması IV. II. Göktürk Devleti\'nin kurulması', 'IV', ['III', 'II', 'I'], 'Sıralama: Katalon Savaşı (451), Göktürklerin bölünmesi (582), II. Göktürk\'ün kuruluşu (681), Uygurların yıkılışı (840). Üçüncü olay 681\'dir.'),
  ('Asparuh\'un Tuna Bulgar Devleti\'ni kurması (681) ile Han Boris\'in Hristiyanlığı kabul etmesi (864) arasındaki süre için aşağıdakilerden hangisi doğrudur?', 'İki yüzyıldan kısa, bir buçuk yüzyıldan uzundur', ['Bir yüzyıldan kısadır', 'Tam olarak iki yüzyıla, yani 200 yıla eşittir', 'Üç yüzyıldan uzundur'], '864 − 681 = 183 yıldır; bu süre 150 yıldan uzun, 200 yıldan kısadır.'),
  ('Aşağıdaki hükümdar-devlet eşleştirmelerinden hangisi yanlıştır?', 'Sulu Kağan – Hazar Kağanlığı', ['Mukan Kağan – Göktürk Devleti', 'Moyun Çor – Uygur Kağanlığı', 'Rua – Avrupa Hun Devleti'], 'Sulu Kağan Türgiş hükümdarıdır; diğer eşleştirmeler doğrudur.'),
  ('Göktürkler ile Uygurlar karşılaştırıldığında aşağıdakilerden hangisi yalnız Uygurlar için söylenebilir?', 'Maniheizmi devlet dini olarak benimsemeleri', ['Ötüken\'i yönetim merkezi yapmaları', 'Göktürk alfabesiyle yazıt dikmeleri', 'Çin ile ilişkilerde ipek ticaretinden yararlanmaları'], 'Ötüken, Göktürk alfabesi ve ipek ticareti iki devlette ortaktır; Maniheizmi devlet dini yapan ise yalnız Uygurlardır.'),
  ('Asya Hunları ile Göktürklerin ortak özelliklerinden biri aşağıdakilerden hangisidir?', 'Merkezlerinin Ötüken çevresinde bulunması', ['Avrupa\'da Katalon Ovası\'nda savaşmaları', 'Maniheizmi resmî din olarak kabul etmeleri', 'Kansu ve Turfan\'da devlet kurmaları'], 'Hem Hunlar hem Göktürkler Ötüken bölgesini merkez edinmiştir; diğer seçenekler bu iki devlete uymaz.'),
  ('Avrupa Hunları ile Avrupa Avarları arasındaki ortak noktalardan biri aşağıdakilerden hangisidir?', 'Macaristan ovasını merkez edinip Bizans\'tan vergi almaları', ['İkisinin de Musevi bir yönetici sınıfa sahip olması', 'İkisinin de Orhun Vadisi\'ne yazıt dikerek tarihlerini anlatması', 'İkisinin de Kiev prensi tarafından yıkılması'], 'Her iki devlet de Pannonia\'da merkez kurmuş ve Bizans\'ı haraca bağlamıştır.'),
  ('Hazarlar ile Tuna Bulgarları karşılaştırıldığında hangisi doğrudur?', 'Tuna Bulgar yöneticileri Hristiyanlığı, Hazar yöneticileri Museviliği benimsemiştir', ['Her iki devletin yöneticileri de Maniheizmi benimsemiştir', 'Hazarlar Hristiyanlığı, Tuna Bulgarları Museviliği benimsemiştir', 'Her iki devlet de İslamiyet\'i resmî din yaparak Abbasi halifesine elçi göndermiştir'], 'Tuna Bulgarları 9. yüzyılda Hristiyanlığa, Hazar yönetici sınıfı ise Museviliğe geçmiştir.'),
  ('Bir öğrenci \'İslamiyet öncesi Türk devletleri genellikle kısa ömürlü olmuştur\' diyor. Bu durumun nedenleri arasında aşağıdakilerden hangisi gösterilemez?', 'Devletlerin tek bir din etrafında katı biçimde örgütlenmesi', ['Taht kavgaları ve veraset belirsizliği', 'Bağlı boyların fırsat buldukça ayaklanıp ayrılması', 'Çin gibi komşuların bölücü politikaları'], 'Kısa ömürlülüğün nedenleri taht kavgaları, boy ayaklanmaları ve dış kışkırtmalardır. Bu devletler dinî açıdan hoşgörülüydü, katı bir din örgütlenmesi yoktu.'),
  ('Aşağıdakilerden hangisi Göktürk Devleti\'nin kuruluşundan önce yaşanmıştır?', 'Ak Hunların Sasani hükümdarı Firuz\'u yenmesi', ['İstemi Yabgu\'nun Bizans\'a Soğdlu bir elçi göndermesi', 'Kürşad\'ın Tang sarayını basması', 'Tonyukuk yazıtının dikilmesi'], 'Ahşunvar\'ın Firuz\'u yenmesi 484\'tedir; Göktürkler 552\'de kurulmuştur. Diğer olaylar Göktürk kuruluşundan sonradır.'),
  ('Aşağıdaki gelişmelerden hangisi diğerlerinden sonra yaşanmıştır?', 'Turfan Uygurlarının Moğollara bağlanması', ['Hazar Kağanlığı\'nın Svyatoslav\'ın saldırılarıyla çökmesi', 'Kırgızların Uygur Kağanlığı\'nı yıkması', 'Bögü Kağan\'ın Maniheizmi kabul etmesi'], 'Turfan Uygurlarının bağlanması 1209\'dadır. Hazarların çöküşü 960\'lar, Uygurların yıkılışı 840, Maniheizmin kabulü 762 dolaylarıdır.'),
  ('Tarihçiler İslamiyet öncesi Türk tarihini yazarken Çin yıllıklarına çok başvurur. Bu kaynakları kullanırken dikkat edilmesi gereken en önemli nokta nedir?', 'Olayları Çin\'in bakış açısıyla ve çoğu zaman Türklere düşmanca anlatabilmeleri', ['Çin yıllıklarının yalnızca Türkçe yazılmış olması', 'Çin yıllıklarının olayları hiçbir tarih vermeden yalnızca efsane biçiminde anlatması', 'Çinlilerin Türkleri hiç tanımaması'], 'Çin yıllıkları ayrıntılı ve tarihlidir; ancak rakip bir devletin bakışını yansıttığından Türk kaynakları ve diğer verilerle karşılaştırılmalıdır.'),
  ('On iki hayvanlı Türk takviminde aşağıdaki hayvanlardan hangisinin adını taşıyan bir yıl yoktur?', 'Kurt', ['Koyun', 'At', 'Sıçan'], 'Takvimdeki hayvanlar sıçan, öküz, pars, tavşan, ejderha (lu), yılan, at, koyun, maymun, tavuk, köpek ve domuzdur; kurt bunlar arasında yer almaz.'),
  ('Türgişlerin Soğd tarzında, ortası delik ve üzerinde Soğd harfleriyle yazı bulunan bakır sikkeler bastırması neyi gösterir?', 'Ticaretle ilgilenen ve yerleşik çevrelerle kaynaşan bir devlet yapısını', ['Türgişlerin yalnız takas ekonomisi kullandığını', 'Türgişlerin Bizans\'a bağlı bir vasal olup onun parasını kullandığını', 'Türgişlerin yazıyı hiç kullanmadığını'], 'Sikke basmak para ekonomisine katılımı, Soğd harflerinin kullanılması da Türgişlerin ticaret merkezleriyle kültürel etkileşimini gösterir.'),
  ('Göktürkler döneminde \'Türk\' adının Bizans, Sasani ve Çin kaynaklarında aynı anda geçmeye başlaması neyi gösterir?', 'Göktürklerin üç büyük medeniyetle aynı dönemde ilişki kuran bir dünya gücü olduğunu', ['Göktürklerin bu üç devleti de fethedip yönettiğini', 'Türk adının bu üç devletin yazarları tarafından birbirinden habersiz uydurulduğunu', 'Göktürklerin yalnız Çin\'le ilişki kurduğunu'], 'Göktürklerin batıda Bizans ve Sasanilerle, doğuda Çin\'le diplomatik ve askerî ilişkileri, onları dönemin büyük güçlerinden biri hâline getirmiştir.'),
  ('Göktürklerin Juan-juanlara karşı ayaklanmadan önce Altay Dağları\'nın güney eteklerinde yaşadığı bilgisi, onların hangi ekonomik etkinlikte uzmanlaşmasıyla uyumludur?', 'Demir madenciliği ve işçiliği', ['Pirinç tarımı', 'Balıkçılık ve göllerde kayıkla taşımacılık', 'İpek böcekçiliği'], 'Altay bölgesi maden bakımından zengindir; Göktürklerin Juan-juanlara demirci olarak hizmet etmesi bu coğrafi ortamla açıklanır.'),
  ('Göktürk yazıtlarında \'Otuz Tatar\' ve \'Kıtay\' gibi adların geçmesi, bu metinlerin hangi açıdan kaynak değeri taşıdığını gösterir?', 'Göktürklerin doğusundaki komşu halklar hakkında bilgi vermesi', ['Bizans sarayının iç siyasetini ve imparatorlar arasındaki çekişmeleri ayrıntılı anlatması', 'Arap fetihlerinin kronolojisini vermesi', 'Hindistan\'daki devletleri tanıtması'], 'Yazıtlar Tatarlar ve Kıtaylar (Kitanlar) gibi doğu komşularıyla yapılan savaşları da anlatır; bu nedenle bölgenin etnik yapısı için önemli bir kaynaktır.'),
  ('Asya Hunlarında veliahdın genellikle \'Sol Bilge Kral\' unvanıyla devletin doğu kanadını yönetmesi hangi uygulamanın erken bir örneğidir?', 'İkili teşkilatın', ['İkta sisteminin', 'Devşirme sisteminin', 'Tımar sisteminin'], 'Hunlarda ülke doğu ve batı kanatlarına ayrılmış, doğu kanadı veliahda verilmiştir; bu, sonraki Türk devletlerinde görülen ikili teşkilatın erken biçimidir.'),
  ('Avrupa Hun hükümdarı Uldız\'ın 400 yılında Doğu Roma\'ya isyan eden Got komutanı Gaynas\'ı yenip başını İstanbul\'a göndermesi, Hunların o dönemde Roma ile ilişkisi hakkında ne gösterir?', 'Hunların zaman zaman Roma\'nın müttefiki olarak Gotlara karşı savaştığını', ['Hunların Roma\'yı tamamen fethettiğini', 'Hunların Gotlarla birleşip Roma\'yı yıkarak İstanbul\'u ele geçirdiğini', 'Hunların Roma ile hiç ilişki kurmadığını'], 'Uldız döneminde Hunlar Roma\'ya karşı her zaman düşmanca değil, çıkarlarına göre müttefikçe de davranmış; Got isyancılarına karşı Roma\'ya yardım etmiştir.'),
  ('Katalon Ovası Savaşı\'nda Attila\'nın karşısındaki Romalı komutan Aetius\'un gençliğinde bir süre rehine olarak Hunların yanında yaşamış olması, onun hangi yönüne katkıda bulunmuştur?', 'Hunları ve savaş usullerini yakından tanımasına', ['Hristiyanlığı Hunlara yaymasına', 'Hun tahtına aday gösterilmesine', 'Bizans\'ın Hunlara ödediği yıllık vergiyi tümüyle durdurabilmesine'], 'Aetius Hunlar arasında yaşadığı için onların dilini, liderlerini ve savaş tarzını tanımış; uzun süre Hun paralı askerlerinden de yararlanmıştır.'),
  ('Kaynaklara göre Attila\'nın 453\'teki ölümü nasıl gerçekleşmiştir?', 'Düğün gecesinden sonra burun kanaması sonucu boğularak', ['Katalon Ovası\'nda yaralanarak', 'Papa\'nın gönderdiği zehirle', 'Bizans\'a karşı Tuna üzerinde yapılan bir nehir savaşında ok yarasıyla'], 'Jordanes\'e göre Attila, İldiko ile evlendiği gecenin sabahında burun kanamasından kendi kanında boğulmuş olarak bulunmuştur.'),
  ('Ak Hunların, tahttan indirilen Sasani hükümdarı I. Kavad\'ı 5. yüzyılın sonunda yeniden tahta çıkarmasına yardım etmesi neyi gösterir?', 'Ak Hunların Sasani iç siyasetini etkileyebilecek güçte olduğunu', ['Sasanilerin Ak Hunları yönettiğini', 'Ak Hunların Bizans\'a bağlı bir müttefik olarak hareket ettiğini', 'Ak Hunların Sasanilerle hiç ilişki kurmadığını'], 'Kavad, Ak Hunlara sığınmış ve onların desteğiyle tahtını geri almıştır; bu, Ak Hunların İran üzerindeki etkisini gösterir.'),
  ('Batı Göktürklerin \'On Ok\' adıyla anılmasında boy beylerine birer ok verilmesinin simgesel anlamı aşağıdakilerden hangisidir?', 'Okun yetki ve bağlılık işareti olarak kullanılması', ['Okun yalnızca av aracı sayılması', 'Okun ticarette para yerine geçip kervanlarda değiş tokuş edilmesi', 'Okun dinî bir kurban olarak sunulması'], 'Eski Türklerde ok, egemenlik ve yetkinin simgesiydi; boy beylerine ok verilmesi onların kağana bağlı yöneticiler olduğunu gösterirdi.'),
  ('Uygur kağanı Moyun Çor\'un Şine Usu yazıtında Selenga Irmağı kıyısında Soğdlu ve Çinlilere bir şehir yaptırdığını anlatması neyi gösterir?', 'Uygurların yerleşik yapılar kurmak için yabancı ustalardan yararlandığını', ['Uygurların Selenga\'yı Çin\'e bıraktığını', 'Uygurların şehirleri yıkmayı amaçladığını', 'Soğdluların Uygurları fethedip Selenga boyunda kendi şehirlerini kurduğunu'], 'Moyun Çor\'un Bay Balık\'ı Soğdlu ve Çinli ustalara yaptırması, Uygurların yerleşik kültüre geçişte yabancı birikimden yararlandığını gösterir.'),
  ('Bugün Slav dili konuşulan bir Balkan ülkesinin adının bir Türk topluluğundan gelmesi aşağıdaki olgulardan hangisini en iyi örnekler?', 'Göç eden Türk topluluklarının dillerini yitirse de adlarını yaşatabildiğini', ['Türk dilinin Balkanlarda resmî dil olduğunu', 'Slav halklarının ilk yurdunun Orta Asya bozkırları olduğunu kanıtladığını', 'Balkanların hiç göç almadığını'], 'Bulgaristan adını Türk kökenli Bulgarlardan alır; ancak Tuna Bulgarları Slavlaşmış, ad ise devlet ve halk adı olarak yaşamıştır.'),
  ('Kurganlarda bulunan Çin ipeği, İran kumaşı ve yerel keçe ürünlerinin bir arada bulunması aşağıdakilerden hangisinin kanıtıdır?', 'Bozkır topluluklarının uzak bölgelerle ticari ve kültürel bağ kurduğunun', ['Bozkırda hiç ticaret yapılmadığının', 'Bütün ürünlerin bozkırda üretildiğinin', 'Kurganların yalnızca Çinli tüccarlara ve onların ailelerine ait olduğunun'], 'Farklı bölgelerden gelen eşyalar, bozkır halklarının Çin\'den İran\'a uzanan geniş bir ticaret ağının parçası olduğunu gösterir.'),
  ('Çin kaynaklarına göre Asya Hunlarında sonbaharda yapılan büyük toplantıda insanların ve hayvanların sayılması en çok hangi devlet ihtiyacıyla ilgilidir?', 'Vergi ve asker gücünün belirlenmesi', ['Dinî bayramların takvime göre düzenlenmesi', 'Çin\'e gönderilecek elçilerin seçilmesi', 'Hükümdarın yeni eşini seçmesi'], 'Nüfus ve sürülerin sayılması, devletin ne kadar asker toplayabileceğini ve ne kadar vergi alabileceğini bilmesini sağlıyordu.'),
  ('MÖ 200\'de Pai-teng\'de kuşatılan Çin imparatorunun adamlarının Mete\'nin hatununa armağanlar göndererek kuşatmanın kaldırılması için aracılık istemesi neyi gösterir?', 'Hatunun hükümdar üzerinde siyasi etkisi bulunduğunu', ['Mete\'nin hatunun sözünü hiç dinlemediğini', 'Hatunun Çin sarayının casusu olarak Hunların arasına gönderildiğini', 'Hunlarda kadınların sarayda bulunmadığını'], 'Çin kaynaklarına göre armağanlar alan Hun hatunu Mete\'yi kuşatmayı kaldırmaya ikna etmiştir; bu, hatunun devlet işlerindeki etkisini gösterir.'),
  ('630 dolaylarında Batı Göktürk hükümdarı Tong Yabgu ile Yedisu\'daki ordugâhında görüşüp ondan geçiş izni ve korumalar alan Çinli Budist keşişin bu yolculuğu neyi gösterir?', 'Batı Göktürklerin Orta Asya\'daki kervan yollarının güvenliğini sağladığını', ['Göktürklerin Budizmi yasakladığını', 'Batı Göktürklerin Çin\'e bağlı olduğunu', 'Göktürklerin yabancıların ülkelerine girmesini kesinlikle yasakladığını'], 'Tong Yabgu\'nun verdiği mektuplar ve korumalarla keşiş Orta Asya\'yı güvenle geçmiştir; bu, Göktürklerin ticaret ve yolcu yollarını denetlediğini gösterir.'),
  ('Bilge Kağan döneminde Tang hanedanıyla ilişkilerin yumuşaması, Kül Tigin\'in mezar külliyesinin yapımında hangi biçimde kendini göstermiştir?', 'Çin\'den ustaların gönderilmesi ve Çince bir metnin yazıta eklenmesi', ['Çin ordusunun Ötüken\'e yerleşmesi', 'Yazıtın tümüyle Çince yazılıp Türkçe metne hiç yer verilmemesi', 'Kül Tigin\'in Çin\'e gömülmesi'], 'Bilge Kağan, Çin imparatorundan ustalar getirtmiş; yazıtın bir yüzüne de imparatorun Çince taziye metni yazılmıştır.'),
  ('720 dolaylarında Tang\'ın Basmil ve Kitanlarla Göktürklere karşı kurduğu ittifakın, Tonyukuk\'un Basmilleri ani bir saldırıyla yenmesiyle bozulması onun hangi niteliğini öne çıkarır?', 'Düşman ittifakı birleşmeden onu parça parça yenme stratejisini', ['Savaştan kaçınıp yalnız diplomasiye güvenmesini', 'Çin\'e teslim olup vergi ödemeyi önermesini', 'Göçebe hayatı terk etme düşüncesini'], 'Tonyukuk, müttefikler birleşmeden en yakın tehdit olan Basmillere hızla saldırmış ve ittifakı dağıtmıştır.'),
  ('758\'de Tang imparatorunun öz kızını Uygur kağanı Moyun Çor ile evlendirmesi, daha önceki Çin evlilik politikasından nasıl ayrılır ve neyi gösterir?', 'Uzak akraba yerine öz kızın verilmesi, Uygur desteğinin Çin için hayati olduğunu gösterir', ['Çin\'in Uygurları hiç önemsemeyip onlara değersiz bir gelin gönderdiğini gösterir', 'Uygurların Çin\'e bağlı bir eyalet olup imparatora vergi ödediğini gösterir', 'Evliliğin Uygurlarca reddedilip prensesin Çin\'e geri yollandığını gösterir'], 'Çin, yabancı hükümdarlara genellikle uzak akraba prensesler verirdi; An Lu-şan İsyanı\'nda Uygur yardımına muhtaç olunca imparator öz kızını göndermiştir.'),
  ('Göktürkler ve Uygurların Çin ile ilişkileri karşılaştırıldığında aşağıdakilerden hangisi söylenebilir?', 'Göktürkler Çin\'e karşı bağımsızlık mücadelesiyle, Uygurlar Tang\'a askerî yardımla öne çıkar', ['İki devlet de Çin\'e hiç savaş açmamıştır', 'Göktürkler Çin\'i tümüyle fethetmiş, Uygurlar Çin\'e bağlanmıştır', 'İki devletin de Çin ile ticari ilişki kurmayıp sınır pazarlarını tümüyle kapattığı'], 'Göktürk yazıtları Çin\'e karşı uyarılarla doludur; Uygurlar ise An Lu-şan İsyanı\'nda Tang\'ı kurtararak bu ilişkiden ekonomik kazanç sağlamıştır.'),
  ('Sasani hükümdarı IV. Hürmüz\'ün annesinin bir Türk prensesi olduğu ve bu nedenle onun \'Türkzâde\' olarak anıldığı bilinir. Bu evlilik hangi dönemdeki ilişkilerle bağlantılıdır?', 'Göktürk-Sasani ittifakıyla Ak Hunların yıkıldığı dönem', ['Hazar-Arap savaşlarının Kafkasya\'da en yoğun yaşandığı dönem', 'Avrupa Hunlarının Galya seferleri dönemi', 'Uygurların Maniheizmi kabul ettiği dönem'], 'Göktürkler ve Sasaniler Ak Hunlara karşı ittifak yaptığı 6. yüzyıl ortasında evlilik yoluyla akrabalık kurmuştur.'),
  ('Uygurların Turfan yakınındaki merkezi Beşbalık\'ın adındaki \'balık\' sözcüğü eski Türkçede hangi anlama gelir?', 'Şehir', ['Göl', 'Kale burcu', 'Pazar yeri'], 'Eski Türkçede \'balık\' şehir demektir; Beşbalık \'beş şehir\', Ordu-Balık \'saray şehri\' anlamına gelir.'),
  ('Germen halklarının ortaçağ destanı Nibelungen\'de \'Etzel\' adıyla yer alan hükümdar kimdir?', 'Attila', ['Teoman', 'Bayan Kağan', 'Krum Han'], 'Nibelungen Destanı\'nda Hun kralı Etzel olarak geçen kişi Attila\'dır; bu, Hunların Germen hafızasında bıraktığı derin izi gösterir.'),
  ('Eski Rus yıllıklarına göre Kiev çevresindeki bazı Slav boylarının 9. yüzyılda vergi ödediği Türk devleti hangisidir?', 'Hazar Kağanlığı', ['Avrupa Hun Devleti', 'Uygur Kağanlığı', 'Göktürk Devleti'], 'Rus yıllıkları, Kiev Ruslarının güçlenmesinden önce bazı Slav boylarının Hazarlara vergi verdiğini kaydeder.'),
  ('Hazar Kağanlığı\'nın İdil\'in aşağı kesimindeki konumu, ticarette hangi yönde akan malların denetimini kolaylaştırmıştır?', 'Kuzeyin kürk ve bal gibi ürünleri ile güneyin gümüşü ve kumaşları', ['Batı Avrupa\'nın şarabı ile Afrika\'nın fildişi', 'Hindistan\'ın baharatı ile Japonya\'nın pirinç ve ipek ürünleri', 'Amerika\'nın gümüşü ile Çin\'in porseleni'], 'İdil boyu, kuzey ormanlarının kürk, bal ve köle ticaretini güneydeki İslam dünyasının gümüş ve kumaşlarıyla birleştiren bir yoldu.'),
  ('Bizans tarihçisi Prokopios\'un Ak Hunları diğer Hunlardan ayırırken vurguladığı özellik aşağıdakilerden hangisidir?', 'Göçebe değil yerleşik yaşamaları ve tek bir hükümdarca düzenli yönetilmeleri', ['Hiç ata binmeyip yalnızca gemilerle Hazar kıyılarında savaşmaları', 'Hristiyanlığı resmî din yapmaları', 'Avrupa\'da Galya\'yı ele geçirmeleri'], 'Prokopios, Ak Hunların diğer Hunlar gibi göçebe olmadığını, verimli topraklarda yaşadığını ve tek bir kral altında düzenli yönetildiğini yazar.'),
  ('Peçeneklerin 968\'de Kiev\'i kuşatması sırasında Kiev prensi Svyatoslav\'ın Balkanlarda sefer yapıyor olması, Bizans\'ın kuzey politikası hakkında hangi çıkarımı destekler?', 'Bizans\'ın bir bozkır gücünü diğer rakiplerine karşı baskı aracı olarak kullanabildiğini', ['Peçeneklerin Ruslarla kalıcı bir ittifak kurduğunu', 'Bizans\'ın Rusları hiç tanımadığını ve onlarla hiçbir ilişki kurmadığını', 'Peçeneklerin Kiev\'i başkent yaptığını'], 'Svyatoslav Bizans\'ın kuzeyinde güçlenirken Peçenekler onun başkentini kuşatmıştır; Bizans\'ın Peçeneklerle ilişkisi bu tür baskıları mümkün kılıyordu.'),
  ('Karadeniz\'in kuzeyindeki bozkırlarda bulunan ve Kuman-Kıpçaklara ait olduğu kabul edilen insan biçimli taş heykeller hangi eski Türk geleneğinin sürdüğünü gösterir?', 'Mezar başına taş heykel ve anıt dikme geleneğinin', ['Mumyalama ve ölüyü tapınakta saklama geleneğinin', 'Piramit yapma geleneğinin', 'Ölüleri yakma geleneğinin'], 'Kuman taş heykelleri, Göktürk döneminden beri bozkırda görülen mezar başına insan biçimli taş dikme geleneğinin batıdaki devamıdır.'),
  ('Macaristan\'da bugün bazı bölge adlarında \'Kun\' sözcüğünün bulunması hangi tarihî gelişmenin izidir?', '13. yüzyılda Kumanların Macaristan\'a yerleştirilmesi', ['Avrupa Hunlarının 5. yüzyılda Galya\'yı alması', 'Hazarların İdil deltasında İtil\'i kurması', 'Göktürklerin Bizans\'a elçi göndermesi'], 'Macarlar Kumanlara \'Kun\' derdi; Moğol istilası döneminde Macaristan\'a yerleşen Kumanların yaşadığı bölgeler bu adla anılmıştır.'),
  ('Turfan Uygurlarında 840 sonrasında Maniheizmin yanında giderek yaygınlaşan ve pek çok mağara tapınağı ile çeviri esere konu olan din hangisidir?', 'Budizm', ['Zerdüştlük', 'Musevilik', 'Hristiyanlığın Ortodoks kolu'], 'Turfan bölgesinde Budizm güçlenmiş; Bezeklik gibi mağara tapınakları ve Uygurcaya çevrilen Budist metinler bu dönemin ürünüdür.'),
  ('Turfan ve Dunhuang\'da bulunan el yazmalarının Uygurca, Soğdca, Çince ve Toharca gibi farklı dillerde olması bu bölge hakkında neyi gösterir?', 'Çok dilli ve çok kültürlü bir ticaret ve kültür kavşağı olduğunu', ['Bölgede yalnız tek bir dilin konuşulduğunu', 'Bölgede hiç yazı kullanılmadığını ve bilginin sözlü aktarıldığını', 'Bölgenin Avrupa\'dan geldiğini'], 'İpek Yolu üzerindeki bu vahalar farklı halkların ve dinlerin buluştuğu merkezlerdi; çok dilli metinler bu çeşitliliği yansıtır.'),
  ('Kırgızların 840\'ta Uygur başkentini aldıktan sonra Ötüken\'i kalıcı bir merkez yapmayıp ağırlıklı olarak Yenisey yurdunda kalmaları, bölge için hangi sonucu doğurmuştur?', 'Moğolistan bozkırında Türk siyasi egemenliğinin zayıflamasına zemin hazırlamıştır', ['Ötüken\'in yeniden Uygurlarca yönetilmesine yol açmıştır', 'Kırgızların Avrupa\'ya göç edip Pannonia\'ya yerleşmesine neden olmuştur', 'Hazarların Ötüken\'e yerleşmesini sağlamıştır'], 'Kırgızların Ötüken\'de güçlü bir merkez kurmaması ve 10. yüzyılda Kitanlarca çıkarılması, bölgede Türk egemenliğinin sona ermesini kolaylaştırmıştır.'),
  ('Hazarlar, Peçenekler ve Kumanlar gibi Karadeniz\'in kuzeyindeki Türk topluluklarının Bizans için ortak önemi aşağıdakilerden hangisidir?', 'Bizans\'ın kuzey sınırının güvenliğini doğrudan etkilemeleri', ['Bizans\'a Akdeniz\'de donanma desteği vermeleri', 'Bizans\'ın Anadolu\'daki eyaletlerini valiler aracılığıyla yönetmeleri', 'Bizans\'a Hindistan ipeğini getirmeleri'], 'Bu topluluklar Tuna ve Kırım sınırında Bizans\'ın hem müttefiki hem tehdidi olmuş; kuzey sınırının güvenliği onlarla ilişkiye bağlıydı.'),
  ('Çin kaynaklarında Asya Hunları hangi adla anılır?', 'Hiung-nu (Xiongnu)', ['Tu-kiu (Tujue)', 'Hui-he (Huihe)', 'Jou-jan (Rouran, Avar)'], 'Çin yıllıkları Hunları Hiung-nu olarak kaydeder. Tu-kiu Göktürkleri, Hui-he Uygurları, Jou-jan ise Juan-juanları ifade eder.'),
  ('Göktürk kağanlarının mensup olduğu hanedan ailesi hangi adla bilinir?', 'Aşina', ['Kınık', 'Kayı', 'Yağlakar'], 'Göktürk hanedanı Aşina soyundandır. Yağlakar Uygur kağanlarının, Kınık ve Kayı ise sonraki Oğuz boylarının adıdır.'),
  ('Avrupalı bilim insanlarının Göktürk yazısını \'runik yazı\' olarak adlandırmasının nedeni nedir?', 'Harflerin İskandinav run yazısına biçimce benzemesi', ['Yazının İskandinavlar tarafından icat edilmesi', 'Yazıtların İskandinavya\'da bulunup oradan Moğolistan\'a taşınması', 'Yazının yalnız taşa değil buza da yazılması'], 'Göktürk harflerinin köşeli görünümü Kuzey Avrupa\'nın run harflerini andırdığı için bu adlandırma yapılmıştır; iki yazı arasında köken bağı yoktur.'),
  ('463\'te bazı Ogur boylarının Bizans\'a elçi gönderip Sabirlerin baskısıyla yurtlarından çıktıklarını, Sabirlerin de Avarların baskısına uğradığını bildirmesi göçlerin hangi özelliğini gösterir?', 'Bir topluluğun hareketinin diğerlerini zincirleme biçimde yerinden oynatmasını', ['Göçlerin yalnızca tek bir topluluğu etkileyip komşu boylara hiç dokunmamasını', 'Göçlerin her zaman doğudan batıya değil kuzeyden güneye olmasını', 'Göçlerin yalnızca deniz yoluyla yapılmasını'], 'Avarlar Sabirleri, Sabirler de Ogurları itmiştir; bu, bozkırda göçlerin domino etkisiyle yayıldığını gösterir.'),
  ('Sasani komutanı Behram Çubin\'in 588\'de Göktürk ordusunu Horasan\'da yenmesi, Göktürk-Sasani ilişkilerinin hangi evresine aittir?', 'Ak Hunların yıkılışından sonra başlayan rekabet ve savaş evresine', ['İki devletin ilk kez Ak Hunlara karşı ittifak kurduğu evreye', 'Göktürklerin Sasanilere bağlandığı evreye', 'Sasanilerin Göktürk yurdunu ele geçirdiği evreye'], 'Ak Hunlar ortadan kalkınca Göktürkler ile Sasaniler komşu olmuş, ipek ticareti ve sınır yüzünden savaşa girmişlerdir.'),
  ('630\'da Doğu Göktürkleri yenen Tang imparatoru Taizong\'un Türk boy beylerince \'Tengri Kağan\' olarak tanınması neyi gösterir?', 'Çin imparatorunun bozkırda meşruiyet için Türk unvanı kullandığını', ['Taizong\'un Türk soyundan geldiğini', 'Göktürklerin Tang\'ı yenip imparatoru atadığını', 'Taizong\'un Ötüken\'e taşınıp oradan Çin\'i yönetmeye başladığını'], 'Tang imparatoru, Türk boylarını yönetebilmek için bozkırın siyasi diline uygun olarak \'Tengri Kağan\' unvanını kullanmıştır.'),
  ('Turfan Uygur Devleti\'nin başkentlerinden biri olan ve kalıntıları Turfan yakınında bulunan şehir hangisidir?', 'Koço (Hoço)', ['İtil (Atil)', 'Pliska', 'Ordu-Balık'], 'Turfan Uygurlarının kış merkezi Koço, yaz merkezi Beşbalık\'tır. İtil Hazarların, Pliska Tuna Bulgarlarının, Ordu-Balık ise Ötüken\'deki Uygur Kağanlığı\'nın merkezidir.'),
  ('Hazarların 730\'da Erdebil yakınlarında Arap ordusunu yenip komutanı Cerrah\'ı öldürmesi, Hazar-Arap savaşları için ne gösterir?', 'Hazarların Kafkasların güneyine kadar etkili akınlar yapabildiğini', ['Hazarların Araplara bağlandığını', 'Arapların Hazar başkentini alıp kağanı İslam\'a geçirdiğini', 'Hazarların hiç savaşmadığını'], 'Erdebil zaferi, Hazarların savunmanın ötesine geçip Azerbaycan içlerine kadar ilerleyebilecek güçte olduğunu göstermiştir.'),
  ('Macaristan ovası (Pannonia) farklı dönemlerde farklı toplulukların merkezi olmuştur. Bu topluluklar eskiden yeniye doğru nasıl sıralanır?', 'Avrupa Hunları – Avarlar – Macarlar', ['Avarlar – Avrupa Hunları – Macarlar', 'Macarlar – Avarlar – Avrupa Hunları', 'Avrupa Hunları – Macarlar – Avarlar'], 'Pannonia 5. yüzyılda Hunların, 6.–8. yüzyıllarda Avarların, 9. yüzyıl sonundan itibaren de Macarların yurdu olmuştur.'),
  ('Mete\'nin tahta çıktığı MÖ 209 yılı hangi yüzyıla aittir?', 'MÖ 3. yüzyıl', ['MÖ 2. yüzyıl', 'MÖ 1. yüzyıl', 'MÖ 4. yüzyıl'], 'MÖ 300 ile MÖ 201 arası MÖ 3. yüzyıldır; MÖ 209 bu aralıktadır.'),
  ('Doğu Roma\'nın Hunlara ödediği yıllık vergi Margus Antlaşması\'yla 700 libre altına, Anatolios Antlaşması\'yla 2100 libre altına çıkarılmıştır. Buna göre vergi bu iki antlaşma arasında kaç katına çıkmıştır?', '3', ['2', '4', '6'], '2100 ÷ 700 = 3. Vergi Anatolios Antlaşması\'yla üç katına çıkmıştır.'),
  ('Orhun yazıtlarının uzun ve düzenli cümlelerle, edebî bir anlatımla yazılmış olması Türk dili hakkında hangi sonuca ulaştırır?', 'Türkçenin bu tarihten önce de uzun süre yazı dili olarak işlendiğine', ['Türkçenin bu yazıtlarla birlikte ilk kez konuşulmaya başlandığına', 'Türkçenin yalnızca sözlü bir dil olarak kalıp bir daha yazıya geçirilmediğine', 'Yazıtların Çinliler tarafından yazıldığına'], 'Bu kadar gelişmiş bir anlatım birdenbire ortaya çıkamaz; yazıtlar Türkçenin daha önce de işlenmiş bir yazı geleneğine sahip olduğunu düşündürür.'),
  ('Çin kaynaklarına göre Hun sarayına sığınan Çinli bir danışman, Hun hükümdarına Çin ipeği ve yiyeceklerine düşkünlüğün Hunları Çin\'e bağımlı kılacağını söyleyerek kendi giyim ve beslenme alışkanlıklarını korumasını öğütlemiştir. Bu öğüt hangi kaygıyı yansıtır?', 'Kültürel bağımlılığın siyasi bağımsızlığı zayıflatacağı kaygısını', ['Hunların Çin\'le ticareti genişletip ipek üretimine başlaması gerektiği düşüncesini', 'Hunların yerleşik hayata geçip Çin tarzı kentler kurması gerektiği görüşünü', 'Çin mallarının Hun ordusunu güçlendireceği beklentisini'], 'Danışman, Çin mallarına alışan Hunların Çin\'e bağımlı hâle gelip güçlerini yitireceğini öngörmüştür; benzer bir kaygı yüzyıllar sonra Orhun yazıtlarında da dile getirilir.'),
  ('İslam öncesi Türk devletlerinde ticaretin, diplomasinin ve yazının gelişmesinde Soğdluların rolüne en iyi örnek aşağıdakilerden hangisidir?', 'Uygur alfabesinin Soğd yazısından türetilmesi', ['Orhun yazıtlarının Soğdca yazılması', 'Hazarların Soğd dinini benimsemesi', 'Soğdluların Göktürk kağanı seçilmesi'], 'Uygur alfabesi Soğd yazısından geliştirilmiştir; Soğdlular ayrıca tüccar ve elçi olarak da Türk devletlerinde görev almıştır.'),
  ('Hunlar 375\'te İdil\'i geçtikten sonra Ostrogotlardan önce yenip bir kısmını kendilerine kattıkları, Kafkasların kuzeyinde yaşayan İranî bozkır halkı hangisidir?', 'Alanlar', ['Vandallar', 'Partlar', 'Franklar'], 'Hunlar önce Don çevresindeki Alanları yenmiş, Alanların bir bölümü Hun ordusuna katılmış; ardından Ostrogotlara saldırılmıştır.'),
  ('Batı Roma\'nın son imparatoru Romulus Augustulus\'un babası Orestes\'in gençliğinde Attila\'nın sarayında kâtiplik yapmış olması, Hun yönetimi hakkında neyi gösterir?', 'Hun sarayında yazışmalarda eğitimli Romalıların görev aldığını', ['Attila\'nın Batı Roma\'yı doğrudan yönettiğini', 'Orestes\'in Hun tahtına aday gösterilip Attila\'nın yerine geçtiğini', 'Hunların hiç yazışma yapmadığını'], 'Attila\'nın sarayında Latince ve Yunanca yazışmaları yürüten yabancı kâtipler bulunuyordu; Orestes bunlardan biriydi.'),
  ('Priskos\'un anlatımına göre Attila\'nın sarayında Hunca\'nın yanında Gotça, Latince ve Yunancanın da konuşulması, Hun Devleti\'nin hangi özelliğini yansıtır?', 'Farklı halkları bir araya getiren çok dilli bir yapıya sahip olduğunu', ['Hunların kendi dillerini tümüyle unutup yalnız Latince konuştuğunu', 'Sarayın yalnız Romalılardan oluştuğunu', 'Hun Devleti\'nin bir Roma eyaleti olduğunu'], 'Avrupa Hun Devleti Germen, Alan, Slav ve Roma kökenli unsurları barındırıyordu; sarayda konuşulan diller bu çeşitliliği gösterir.'),
  ('Asya Hunlarının Yüeçileri yenip batıya göçmeye zorlaması, ilerleyen dönemde Orta Asya ve Kuzey Hindistan\'da hangi devletin kurulmasıyla sonuçlanmıştır?', 'Kuşan İmparatorluğu', ['Gupta İmparatorluğu', 'Maurya İmparatorluğu', 'Part Krallığı'], 'Batıya göçen Yüeçiler Baktriya\'ya yerleşmiş ve zamanla Kuşan İmparatorluğu\'nu kurmuştur; bu, bozkırdaki bir gelişmenin uzak bölgeleri nasıl etkilediğini gösterir.'),
  ('Arap tarihçi Mesudi\'ye göre Hazar hükümdarının ordusunda yer alan Müslüman muhafız birliğinin Müslümanlarla savaşa katılmama şartıyla hizmet etmesi neyi gösterir?', 'Hazar yönetiminin farklı dinden askerlerin inançlarına saygı gösterdiğini', ['Hazar ordusunun tamamen Müslüman olduğunu', 'Hazarların hiç asker beslemediğini', 'Müslümanların Hazar tahtına geçip kağanlığı ele geçirdiğini'], 'Muhafızların dinî hassasiyetlerine uygun bir hizmet şartı tanınması, Hazar yönetimindeki dinî hoşgörünün askerî alana da yansıdığını gösterir.'),
  ('Uygur dönemine ait Karabalgasun yazıtının üç dilde yazılmış olması hangi dillerin birlikte kullanıldığını gösterir?', 'Türkçe, Soğdca ve Çince', ['Türkçe, Arapça ve Farsça', 'Türkçe, Yunanca ve Latince', 'Türkçe, Sanskritçe ve Tibetçe'], 'Karabalgasun yazıtında Göktürk harfli Türkçe, Soğdca ve Çince metinler bulunur; bu Uygur devletindeki kültürel çeşitliliği yansıtır.'),
  ('Maniheizmin Uygur devletinde resmî din olmasından sonra Mani din adamlarının kağanın yakın danışmanları arasına girmesi devlet yönetiminde nasıl bir değişime işaret eder?', 'Dinî bir zümrenin siyasi kararlarda etkili olmaya başladığına', ['Kurultayın tümüyle kaldırıldığına', 'Kağanlığın Çin imparatoruna devredilip Uygurların eyalet olduğuna', 'Ordunun dağıtıldığına'], 'Eski Türk devletlerinde güçlü bir din adamları sınıfı yoktu; Uygurlarda Mani rahiplerinin siyasete etkisi bu bakımdan yeni bir durumdur.'),
  ('Göktürklerin batıya kaçan Avarları izleyerek batıya ulaşması ve Karadeniz\'in kuzeyine kadar egemenlik kurması, Göktürkleri hangi devletle doğrudan komşu hâle getirmiştir?', 'Bizans İmparatorluğu', ['Frank Krallığı', 'Japon İmparatorluğu', 'Gupta İmparatorluğu'], 'Göktürk egemenliğinin Kırım ve Kuzey Kafkasya\'ya ulaşması, Göktürkleri Bizans\'la doğrudan temas eden bir güç hâline getirmiştir.'),
  ('Hazarların başkentlerini Kafkasya\'daki şehirlerden kuzeydeki İtil\'e taşımasının en olası nedeni aşağıdakilerden hangisidir?', 'Arap ordularının Kafkasya\'daki baskısından uzaklaşmak', ['Bizans\'a daha yakın olup İstanbul\'la ticareti artırmak', 'Altay Dağları\'na yerleşmek', 'Çin sınırına ulaşmak'], '7.–8. yüzyıllardaki Arap saldırıları Kafkas eteklerindeki şehirleri tehlikeye soktuğundan merkez daha güvenli olan İdil deltasına alınmıştır.'),
  ('Kuman-Kıpçak beylerinin kızlarının Rus prensleriyle sıkça evlendirilmesi iki topluluk arasındaki ilişkiler hakkında neyi gösterir?', 'Savaşların yanında akrabalık ve ittifak ilişkilerinin de kurulduğunu', ['İki topluluğun hiçbir dönemde savaşmayıp hep dost kaldığını', 'Rus prenslerinin Kumanlara bağlı vasal olduğunu', 'Kumanların Rus dilini resmî dil yaptığını'], 'Kumanlar ile Rus knezlikleri sık sık savaşmış, ancak evlilikler yoluyla ittifaklar da kurmuştur; ilişkiler tek yönlü düşmanlık değildir.'),
  ('Göktürklerin bağımsızlıktan önce Juan-juanlara karşı ayaklanan Tölesleri yenerek Juan-juanlara hizmet etmesi, Bumin\'in sonraki talebini nasıl etkilemiştir?', 'Bu hizmete dayanarak Juan-juan kağanından kız istemesine yol açmıştır', ['Bumin\'in Juan-juan tahtına çıkıp iki devleti birleştirmesini sağlamıştır', 'Göktürklerin Çin\'e bağlanmasına yol açmıştır', 'Bumin\'in Bizans\'a sığınmasına neden olmuştur'], 'Bumin, Tölesleri yenerek Juan-juanlara önemli bir hizmet yaptığını düşünmüş ve karşılığında kağanın kızıyla evlenmek istemiştir; reddedilmesi ayaklanmaya yol açmıştır.'),
  ('Çin kaynaklarına göre Göktürklerde at çalan kişinin çaldığının kat kat fazlasını ödemek zorunda olması, bu toplum hakkında neyi gösterir?', 'Atın ekonomide ve savaşta hayati bir değer taşıdığını', ['Atın hiç önemsenmediğini', 'Hırsızlığın suç sayılmayıp töre dışında bırakıldığını', 'Göktürklerin yalnızca deve beslediğini'], 'Atın hem geçim hem savaş için en değerli varlık olması, at hırsızlığının töre tarafından ağır biçimde cezalandırılmasına yol açmıştır.'),
  ('Oğuz Kağan Destanı\'nda büyük oğulların altın yayı, küçük oğulların gümüş okları bulması ve yayın hükümdarlığı, okun elçiyi simgelemesi, boylar arasında hangi ilişkiye işaret eder?', 'Bozokların üstün, Üçokların onlara bağlı kabul edilmesine', ['Bütün boyların tümüyle eşit sayılıp hiçbir ayrım yapılmamasına', 'Üçokların hükümdar soyu olmasına', 'Boyların birbirleriyle sürekli savaşmasına'], 'Yay buyruğu, ok ise bu buyruğa uyan elçiyi simgeler; bu yüzden yayı paylaşan Bozoklar üstün, Üçoklar ise onlara tabi sayılmıştır.'),
  ('Hun ve Göktürk merkezleri ile Uygur başkenti karşılaştırıldığında aşağıdaki farklardan hangisi öne çıkar?', 'Hun ve Göktürk merkezleri seyyar ordugâh iken Uygurlar kalıcı başkent kurmuştur', ['Hunların büyük taş kentler kurup Uygurların ise göçebe ordugâhta kalması', 'Göktürklerin başkentinin Avrupa\'da bulunması', 'Uygurların hiç merkezi olmaması'], 'Göçebe devletlerde merkez, kağanın otağının kurulduğu ordugâhtır; Uygurlar ise Ordu-Balık gibi surlu, kalıcı bir başkent kurmuştur.'),
  ('Mete ile Attila\'nın yönetimleri karşılaştırıldığında ortak bir özellik olarak aşağıdakilerden hangisi söylenebilir?', 'İkisi de dağınık toplulukları birleştirip büyük bir komşuyu vergiye bağlamıştır', ['İkisi de Hristiyanlığı kabul etmiştir', 'İkisi de Çin\'de hanedan kurup Çin tahtına oturmuştur', 'İkisi de devletini Ötüken\'den yönetmiştir'], 'Mete Orta Asya boylarını birleştirip Çin\'i, Attila ise Avrupa\'daki toplulukları birleştirip Bizans\'ı vergiye bağlamıştır.'),
  ('Tuna Bulgar hükümdarı Omurtag\'ın 815 dolaylarında Bizans ile uzun süreli bir barış antlaşması yapması Bulgar devletine öncelikle ne kazandırmıştır?', 'Sınırı güvenceye alıp iç düzen ve imar işlerine yönelme imkânı', ['Bizans tahtını ele geçirme imkânı', 'Hazar Kağanlığı\'nı fethedip İtil\'i başkent yapma imkânı', 'İslamiyet\'i kabul etme imkânı'], 'Krum\'un savaşlarından sonra Omurtag Bizans\'la barış yapmış; bu dönemde Pliska\'da saray ve yapılar inşa edilerek devlet örgütlenmesi güçlendirilmiştir.'),
  ('Hunların Han ordularına karşı zayıflamasından sonra Çin\'in Tarım havzasındaki vaha şehirlerine hâkim olması hangi sonucu doğurmuştur?', 'İpek Yolu\'nun doğu kesiminin uzun süre Çin denetimine girmesi', ['Hunların Avrupa\'dan Asya\'ya geri dönmesi', 'Çin\'in Hindistan\'ı fethederek Ganj ovasına kadar ilerlemesi', 'Vaha şehirlerinin tümüyle boşaltılması'], 'Tarım havzasındaki vahalar kervan yolunun durak noktalarıydı; Hunların çekilmesiyle Han hanedanı bu yolun denetimini ele geçirmiştir.'),
  ('Attila ile birlikte hüküm süren ağabeyi Bleda\'nın 445 dolaylarında ölmesinin Avrupa Hun Devleti\'ndeki sonucu ne olmuştur?', 'Attila\'nın devletin tek hükümdarı olması', ['Devletin ikiye bölünmesi', 'Hunların Bizans\'a bağlanıp ona vergi ödemeye başlaması', 'Tahtın Rua\'ya geçmesi'], 'Bleda\'nın ölümüyle ortak yönetim sona ermiş ve Attila Avrupa Hun Devleti\'nin tek hükümdarı olmuştur.'),
  ('Jordanes\'in aktardığına göre bir çobanın bulup Attila\'ya getirdiği eski bir kılıcın \'savaş tanrısının kılıcı\' sayılması ve Attila\'nın bunu dünya egemenliğine işaret olarak yorumlaması hangi anlayışa benzer?', 'Hükümdarlık yetkisinin kutsal bir kaynaktan verildiği inancına', ['Hükümdarın halk oylamasıyla seçildiği anlayışına', 'Kılıçların bozkırda değerli bir ticaret malı olarak görülmesine', 'Savaşın yasaklanması düşüncesine'], 'Kılıç efsanesi, Attila\'nın egemenliğinin ilahi bir onaya dayandığı düşüncesini yansıtır; bu, eski Türklerdeki kut anlayışıyla benzerlik gösterir.'),
  ('Tuna Bulgar hükümdarlarının soyunu sayan eski listede ilk sırada yer alan ve pek çok tarihçinin Attila ile özdeşleştirdiği \'Avitohol\' adının bulunması neyi gösterir?', 'Bulgar hanedanının meşruiyetini Hun mirasına dayandırdığını', ['Bulgarların Attila\'yı en büyük düşmanları sayıp lanetlediğini', 'Bulgar listesinin Bizans tarafından yazıldığını', 'Attila\'nın Bulgaristan\'da doğduğunu'], 'Bulgar hükümdar listesinin Hun soyuna bağlanması, hanedanın kendini Attila\'nın mirasçısı olarak gördüğünü ve bu bağla saygınlık kazandığını gösterir.'),
  ('Tuna Bulgar hükümdar listesinde yılların hayvan adlarına benzeyen sözcüklerle belirtilmesi, Bulgarların hangi kültürel ortaklığını gösterir?', 'Göktürklerle aynı on iki hayvanlı takvim geleneğini paylaştıklarını', ['Bulgarların Hicri takvim kullandığını', 'Bulgarların Roma takvimini icat ettiğini', 'Bulgarların hiçbir takvim kullanmayıp yılları saymadığını'], 'Bulgar listesindeki yıl adları on iki hayvanlı Türk takvimiyle ilişkilendirilir; bu, Avrupa\'ya göçen Türk topluluklarının ortak bozkır kültürünü koruduğunu gösterir.'),
  ('Göktürk döneminin bilinen en eski yazıtlarından biri olan Bugut yazıtının Türkçe değil Soğdca yazılmış olması ne düşündürür?', 'İlk Göktürk döneminde resmî yazışmalarda Soğd dilinden yararlanıldığını', ['Göktürklerin Türkçeyi hiç konuşmayıp yalnızca Soğdca kullandığını', 'Soğdluların Göktürk Devleti\'ni yönettiğini', 'Yazıtın Bizans\'ta dikildiğini'], '6. yüzyılın sonlarına ait Bugut yazıtının Soğdca olması, Göktürk alfabesiyle Türkçe yazıtların daha sonra yaygınlaştığını ve başlangıçta Soğd yazı geleneğinin kullanıldığını gösterir.'),
  ('8.–9. yüzyıllarda Oğuz boylarının Moğolistan bozkırından batıya, Aral Gölü ve Seyhun çevresine göçmesi sonraki Türk tarihini nasıl etkilemiştir?', 'Oğuzları İslam dünyasıyla komşu yapıp batıya yayılmalarına zemin hazırlamıştır', ['Oğuzların Çin\'e yerleşip orada hanedan kurmasına yol açmıştır', 'Oğuzların tümüyle Avrupa\'ya göçüp Bizans\'a karışmasına neden olmuştur', 'Oğuzların Sibirya\'nın kuzeyine çekilip ormanlarda avcılıkla geçinmesine yol açmıştır'], 'Seyhun boyuna yerleşen Oğuzlar İslam ülkeleriyle sınır komşusu olmuş; bu konum, sonraki yüzyıllarda İran ve Anadolu\'ya yayılmalarının başlangıcı olmuştur.'),
  ('Asya Hunlarında hükümdara bağlı olarak orduyu ve boyları yöneten, Çin kaynaklarında sayıları yirmi dört olarak verilen büyük beylerin bulunması neyi gösterir?', 'Hun Devleti\'nin düzenli ve kademeli bir yönetim yapısına sahip olduğunu', ['Hunların yirmi dört ayrı devlete bölündüğünü', 'Hun hükümdarının hiçbir yetkisi bulunmadığını ve beylerin eşit olduğunu', 'Hunların yalnız yirmi dört kişiden oluştuğunu'], 'Yirmi dört büyük beyin her biri belirli sayıda atlıya komuta eder ve hükümdara bağlı olurdu; bu, merkezî ve kademeli bir yapıyı gösterir.'),
  ('Göktürk egemenliğinin Hazar\'ın kuzeyinden Mançurya\'ya kadar uzanan geniş bozkırları kapsaması dünya ticareti açısından hangi sonucu doğurmuştur?', 'Doğu-batı kara ticaret yollarının büyük kısmının tek bir gücün denetimine girmesi', ['Deniz ticaretinin tümüyle durması', 'Çin\'in ipek üretimini bırakıp bu bilgiyi Bizans\'a satması', 'Avrupa ile Asya arasındaki bağın kopması'], 'Bozkırın büyük kısmını tek elde toplayan Göktürkler, kervan yollarının güvenliğini sağlayarak doğu-batı ticaretinin önemli bir aracısı olmuştur.'),
  ('Kül Tigin yazıtının Çin geleneğine uygun biçimde taştan bir kaplumbağa kaidenin üzerine dikilmiş olması neyi gösterir?', 'Göktürk anıt sanatında Çin etkisinin de bulunduğunu', ['Göktürklerin kaplumbağayı ata saydığını', 'Yazıtın Çin\'de yapılıp parçalar hâlinde Ötüken\'e taşındığını', 'Kaplumbağanın Göktürk tamgası olduğunu'], 'Kaplumbağa kaideli dikili taş bir Çin geleneğidir; Kül Tigin anıtında bu biçimin kullanılması iki kültür arasındaki etkileşimi yansıtır.'),
  ('MÖ 4. yüzyılın sonunda Çin\'in Zhao devletinin kralının askerlerine kuzeydeki göçebeler gibi pantolon giydirip atlı okçuluğu benimsetmesi neyi gösterir?', 'Bozkırın atlı savaş kültürünün yerleşik komşuları da etkilediğini', ['Çin\'in kuzeydeki bozkır halklarını tümüyle fethedip yurtlarına yerleştiğini', 'Göçebelerin Çin giyimini benimsediğini', 'Atlı okçuluğun ilk kez Çin\'de icat edildiğini'], 'Kral Wuling\'in bu reformu, kuzeydeki atlı göçebelere karşı etkili olabilmek için onların giyimini ve savaş tarzını örnek almasıdır.'),
  ('Avrupa Avarlarının 6. ve 7. yüzyıllarda Balkanlara düzenlediği akınlara bağlı Slav toplulukların da katılması, bölge tarihinde hangi sonuca katkıda bulunmuştur?', 'Balkanlarda Slav yerleşiminin yaygınlaşmasına', ['Balkanların Türkçe konuşulan bir bölge olmasına', 'Bizans\'ın Balkanlardaki bütün kentleri boşaltıp Anadolu\'ya çekilmesine', 'Slavların Orta Asya\'ya göç etmesine'], 'Avar egemenliği ve akınları sırasında Slav toplulukları Tuna\'yı geçerek Balkanların içlerine yerleşmiş, bölgenin nüfus yapısı değişmiştir.'),
  ('11. yüzyılda Kıpçakların batıya ilerleyişinin Karadeniz\'in kuzeyindeki diğer Türk toplulukları üzerindeki etkisi aşağıdakilerden hangisidir?', 'Uzları ve Peçenekleri Tuna\'ya ve Balkanlara doğru itmesi', ['Hazar Kağanlığı\'nın İtil merkezli olarak yeniden kurulmasını sağlaması', 'Avarların Pannonia\'ya dönmesine yol açması', 'Uygurların Turfan\'dan ayrılmasına neden olması'], 'Kıpçakların batıya yayılması zincirleme bir baskı yaratmış; Uzlar ve Peçenekler Bizans sınırına, Balkanlara doğru itilmiştir.'),
  ('Mukan Kağan\'ın kızının Kuzey Zhou imparatoruyla evlendirilmesi o dönemdeki Göktürk-Çin ilişkileri hakkında ne gösterir?', 'Kuzey Çin devletlerinin Göktürk desteği için akrabalık aradığını', ['Göktürklerin Çin\'e bağlı olduğunu', 'Mukan\'ın Çin tahtına geçip Kuzey Zhou\'yu yönettiğini', 'Göktürklerin Budizmi yasakladığını'], 'Birbirine rakip Kuzey Çin hanedanları Göktürklerle ittifak kurmak için evlilik bağlarına önem vermiştir; bu, Göktürklerin üstün konumunu gösterir.'),
  ('Bumin\'in Juan-juanlara karşı Batı Wei ile, İstemi\'nin Sasanilere karşı Bizans ile ittifak kurması Göktürk dış politikasının hangi ilkesini yansıtır?', 'Rakibe karşı onun düşmanlarıyla iş birliği yapma', ['Hiçbir devletle ittifak kurmama', 'Her koşulda Çin\'in yanında yer alıp onun düşmanlarıyla savaşma', 'Yalnız Türk boylarıyla anlaşma'], 'Her iki örnekte de Göktürkler, karşı karşıya oldukları güce düşman olan başka bir devletle ittifak kurarak dengeyi kendi lehlerine çevirmiştir.'),
  ('Orhun yazıtlarında geçmiş olayların, yapılan hatalar ve bunların sonuçlarıyla birlikte anlatılması bu metinlerin tarih anlayışı hakkında ne gösterir?', 'Geçmişi gelecek kuşaklara ders ve öğüt vermek için anlattıklarını', ['Yalnızca zaferleri kaydedip yenilgileri gizlediklerini', 'Olayları yalnız tarih sırasıyla, yorum yapmadan listelediklerini', 'Geçmişle hiç ilgilenmediklerini'], 'Yazıtlar yenilgileri ve fetret dönemini de anlatarak beylerin ve halkın hatalarını eleştirir; amaç gelecek kuşakları uyarmaktır.'),
  ('Aşağıdaki Göktürk tarihine ait olaylar eskiden yeniye doğru sıralandığında doğru sıra hangisidir? I. İstemi\'nin Bizans\'a elçi göndermesi II. Kürşad\'ın Tang sarayına baskını III. Bumin\'in Juan-juanları yenmesi IV. Devletin Doğu ve Batı olarak ayrılması', 'III – I – IV – II', ['I – III – IV – II', 'III – IV – I – II', 'III – I – II – IV'], '552 Bumin\'in zaferi, 568 Bizans elçiliği, 582 ayrılma, 639 Kürşad baskını.'),
  ('Aşağıdaki Hazar tarihine ait olaylar eskiden yeniye doğru sıralandığında hangisi doğrudur? I. Sarkel Kalesi\'nin yapılması II. Svyatoslav\'ın İtil\'i alması III. Erdebil\'de Arap ordusunun yenilmesi', 'III – I – II', ['I – III – II', 'II – III – I', 'III – II – I'], 'Erdebil zaferi 730, Sarkel\'in yapımı 9. yüzyılın ilk yarısı, Svyatoslav\'ın seferleri 960\'lardır.'),
  ('Hun hükümdarı Ki-ok\'un yendiği Yüeçi kralının, Bulgar hükümdarı Krum\'un Bizans imparatorunun, Peçenek beyi Küre\'nin de Kiev prensinin kafatasından kadeh yaptırdığı anlatılır. Bu benzerlik neyi düşündürür?', 'Dağınık bozkır toplulukları arasında ortak geleneklerin sürdüğünü', ['Bu olayların aynı yıl ve aynı savaş meydanında yaşandığını', 'Bu geleneğin Bizans\'tan öğrenildiğini', 'Bu toplulukların tek bir hükümdara bağlı olduğunu'], 'Farklı yüzyıllarda ve bölgelerde aynı geleneğin görülmesi, Hun, Bulgar ve Peçenekler gibi bozkır kökenli toplulukların ortak bir kültürel mirası taşıdığını gösterir.'),
  ('9. yüzyılda Kiev çevresindeki bazı Rus hükümdarlarının Batı kaynaklarında \'kağan\' unvanıyla anılması hangi etkiyi gösterir?', 'Hazar Kağanlığı\'nın bölgedeki siyasi geleneği ve saygınlığını', ['Rusların Göktürk soyundan gelip Aşina hanedanına bağlı olduğunu', 'Kağan unvanının Ruslar tarafından icat edildiğini', 'Rusların Çin\'e bağlı olduğunu'], 'Hazarların uzun süre egemen olduğu bölgede \'kağan\' en yüksek hükümdarlık unvanı sayılmış; Rus hükümdarları da saygınlık için bu unvanı benimsemiştir.'),
  ('Uygur Kağanlığı\'nın ilk üç kağanı tahta çıkış sırasına göre nasıl dizilir?', 'Kutluk Bilge Kül – Moyun Çor – Bögü', ['Moyun Çor – Kutluk Bilge Kül – Bögü', 'Bögü – Moyun Çor – Kutluk Bilge Kül', 'Kutluk Bilge Kül – Bögü – Moyun Çor'], 'Kurucu Kutluk Bilge Kül Kağan\'dan (744) sonra Moyun Çor (747), ardından Bögü Kağan (759) tahta çıkmıştır.'),
  ('II. Göktürk Devleti\'nin kağanları tahta çıkış sırasına göre nasıl dizilir?', 'İlteriş Kutluk – Kapgan – Bilge', ['Kapgan – İlteriş Kutluk – Bilge', 'Bilge – Kapgan – İlteriş Kutluk', 'İlteriş Kutluk – Bilge – Kapgan'], 'Devleti 681\'de İlteriş Kutluk kurmuş, 691\'de kardeşi Kapgan, 716\'da da İlteriş\'in oğlu Bilge Kağan tahta geçmiştir.'),
  ('Avrupa Hun hükümdarları hüküm sürdükleri sıraya göre nasıl dizilir?', 'Balamir – Uldız – Rua – Attila', ['Uldız – Balamir – Attila – Rua', 'Rua – Balamir – Uldız – Attila', 'Balamir – Rua – Attila – Uldız'], 'Hunları Avrupa\'ya getiren Balamir\'den sonra Uldız, ardından Rua ve onun ölümünden sonra Attila (Bleda ile birlikte) tahta geçmiştir.'),
  ('Göktürklerde hanedan üyesi olup bir bölgenin ya da ordunun başına getirilen prenslere verilen unvan hangisidir?', 'Şad', ['Tudun', 'Bitikçi', 'Kam'], 'Şad, Göktürk hanedanından gelen ve önemli askerî ya da bölgesel görevlere atanan prenslerin unvanıdır.'),
  ('Maniheizmin İran\'dan Orta Asya\'ya ve oradan Uygurlara yayılmasında en etkin rolü oynayan, İpek Yolu ticaretiyle tanınan topluluk hangisidir?', 'Soğdlular', ['Tibetliler', 'Araplar', 'Gotlar'], 'Mani dininin Orta Asya\'daki taşıyıcıları büyük ölçüde Soğdlu tüccar ve rahiplerdi; Bögü Kağan\'ın getirdiği rahipler de Soğdluydu.'),
  ('Uygurların devlet dini olarak benimsediği Maniheizmin kurucusu Mani hangi ülkede yaşamıştır?', 'Sasani İran\'ında', ['Tang Çin\'inde', 'Bizans\'ta', 'Gupta Hindistan\'ında'], 'Mani 3. yüzyılda Sasani İran\'ında yaşamış ve öğretisini oradan yaymıştır; din, Soğdlular aracılığıyla Orta Asya\'ya ulaşmıştır.'),
  ('Hazarların Museviliği, Tuna Bulgarlarının Hristiyanlığı, Uygurların Maniheizmi ve Budizmi benimsemesi birlikte değerlendirildiğinde hangi genel sonuca ulaşılabilir?', 'Türk toplulukları komşu medeniyetlerin dinlerinden etkilenmiştir', ['Türk toplulukları ortak bir kararla tek bir dini seçmiştir', 'Türkler hiçbir dönemde din değiştirmemiştir', 'Bu dinlerin tamamı Orta Asya\'da doğmuştur'], 'Her topluluk yaşadığı coğrafyada temas kurduğu medeniyetlerin dinlerini benimsemiştir; bu da göçlerin dinî çeşitliliğe yol açtığını gösterir.'),
  ('Mete döneminde Hun egemenliğinin kuzeyde Yenisey bölgesine kadar uzandığı bilinir. Bu dönemde Hunlara bağlanan ve sonraki yüzyıllarda Uygurları yıkacak olan topluluk hangisidir?', 'Kırgızlar', ['Hazarlar', 'Avarlar', 'Peçenekler'], 'Çin kaynaklarına göre Mete kuzeyde Kırgızları da egemenliği altına almıştır; Kırgızlar yüzyıllar sonra 840\'ta Uygur Kağanlığı\'nı yıkmıştır.'),
  ('Hazar Kağanlığı\'nın 7. yüzyılın ortalarında kurulup 960\'larda çöktüğü düşünülürse devletin varlığı yaklaşık ne kadar sürmüştür?', 'Üç yüzyıl', ['Bir yüzyıl', 'Beş yüzyıl', 'Yarım yüzyıl'], 'Yaklaşık 650\'den 965\'e kadar geçen süre üç yüzyıldan biraz fazladır; Hazarlar bu nedenle İslam öncesi Türk devletleri içinde uzun ömürlüler arasındadır.'),
  ('Hazar Kağanlığı\'nın uzun süre varlığını sürdürmesi, Avrupa Hunlarının Attila\'dan sonra hızla dağılmasıyla karşılaştırıldığında Hazarlar için hangi etken öne çıkarılabilir?', 'Ticaret gelirine ve farklı toplulukları bir arada tutan kurumlara dayanması', ['Hiç savaşa girmeyip bütün komşularıyla barış içinde yaşaması', 'Tek bir güçlü hükümdarın kişisel karizmasına bağlı olması', 'Bütün halkın aynı dine geçirilmesi'], 'Hazarlar ticaret yollarından düzenli gelir elde etmiş, kağan-bek yapısı ve dinî hoşgörüyle farklı toplulukları bir arada tutmuştur; Avrupa Hunları ise büyük ölçüde Attila\'nın kişisel gücüne dayanıyordu.'),
  ('Avrupa Avar Kağanlığı\'nın Bayan Kağan\'ın 562\'de başa geçmesinden Şarlman\'ın 796\'da Avar merkezini ele geçirmesine kadar sürdüğü kabul edilirse, bu süre yaklaşık kaç yıldır?', '234', ['134', '334', '196'], '796 − 562 = 234 yıl; yani yaklaşık iki buçuk yüzyıl.'),
  ('Bir tarih öğrencisi \'İslamiyet öncesi Türk devletlerinde kağanın gücü sınırsızdı\' diyor. Aşağıdakilerden hangisi bu yargıyı zayıflatır?', 'Kağanın töreye uymak ve önemli işleri kurultayda görüşmek zorunda olması', ['Kağanın orduya bizzat komuta edip seferlere katılması', 'Kağanın Tanrı\'dan kut aldığına inanılması', 'Kağanın vergi toplatması'], 'Kut, ordu komutası ve vergi kağanın gücünü gösterir; töreye bağlılık ve kurultay ise bu gücün sınırlandırıldığını gösterir.'),
  ('Han hanedanının Hunların batısında yaşayan Wusunların hükümdarına bir prenses göndererek ittifak kurması hangi stratejinin parçasıdır?', 'Hunları batıdan da kuşatıp müttefiklerinden yoksun bırakma', ['Hunlarla kalıcı barış yapıp ticareti artırma', 'Wusunları Hunlara bağlı bir eyalet hâline getirme', 'Çin\'in başkentini batıya taşıma'], 'Han hanedanı Hunları yalnız bırakmak için batıdaki toplulukları kendi tarafına çekmiş; Wusunlarla evlilik ittifakı bu politikanın örneğidir.'),
  ('Tang hanedanının 8. yüzyılın ikinci yarısında Uygurların isteği üzerine Çin\'in bazı şehirlerinde Mani tapınakları açılmasına izin vermesi neyi gösterir?', 'Uygurların siyasi ağırlığının Çin\'de dinî alana da yansıdığını', ['Tang hanedanının Maniheizmi devlet dini yaptığını', 'Uygurların Çin\'i fethedip Tang tahtına kendi kağanlarını oturttuğunu', 'Mani rahiplerinin Tang tahtına geçtiğini'], 'An Lu-şan İsyanı\'ndan sonra Tang\'ın Uygur desteğine muhtaç olması, Uygurların koruduğu Mani dininin Çin\'de de serbestçe örgütlenmesini sağlamıştır.'),
  ('Uygur Kağanlığı\'nın 840\'ta yıkılmasından kısa süre sonra Tang hanedanının Mani tapınaklarını kapatıp bu dinin mensuplarını kovuşturması neyi düşündürür?', 'Maniheizmin Çin\'deki varlığının büyük ölçüde Uygur gücüne dayandığını', ['Uygurların yıkılışında Mani rahiplerinin rolü olmadığını', 'Tang hanedanının Uygurlara son ana kadar askerî yardım gönderdiğini', 'Maniheizmin Çin\'de çoğunluk dini olduğunu'], 'Uygur koruması ortadan kalkınca Tang yönetimi Maniheizme karşı harekete geçmiştir; bu, dinin Çin\'deki konumunun Uygur siyasetine bağlı olduğunu gösterir.'),
  ('Bizans tarihçisi Prokopios\'a göre 6. yüzyılda Sabirlerin Bizans ordusu için hafif ve kolay taşınabilir koçbaşları yapması, onların hangi özelliğini gösterir?', 'Savaş tekniklerinde becerikli ve yeniliklere açık olduklarını', ['Yalnızca deniz savaşında usta olduklarını', 'Kuşatma savaşlarından tümüyle uzak durup hiç kale kuşatmadıklarını', 'Bizans\'a karşı hiç asker vermediklerini'], 'Prokopios, Sabirlerin Bizanslıların bile bilmediği türden hafif koçbaşları yaptığını anlatır; bu, bozkır topluluklarının askerî teknolojide de yaratıcı olabildiğini gösterir.'),
  ('Rus ve Balkan soyluları için kullanılan \'boyar\' sözcüğünün Tuna Bulgarlarının \'boyla\' unvanından geldiği kabul edilir. Bu durum neyi gösterir?', 'Türk kökenli unvanların Slav toplumlarının yönetim diline geçtiğini', ['Slavların ilk yurdunun Orta Asya bozkırları olduğunu kanıtladığını', 'Bulgarların Slav unvanlarını kullandığını', 'Boyarların Türkçe konuştuğunu'], 'Tuna Bulgarlarının yönetici sınıfına ait \'boyla\' unvanı Slavlaşmadan sonra da \'boyar\' biçiminde yaşamış ve Rus ile Balkan soyluluğunun adı olmuştur.'),
  ('Göktürklerin Juan-juanları yenerek bağımsızlık kazandığı dönemde Juan-juanların bir kısmının batıya kaçıp Avrupa\'da Avar adıyla devlet kurması, iki gelişme arasındaki ilişki için ne söyletir?', 'Bozkırdaki bir egemenlik değişiminin Avrupa\'da yeni bir devlet doğurduğunu', ['İki olayın birbirinden tümüyle bağımsız olup aralarında hiçbir bağ bulunmadığını', 'Göktürklerin Avrupa\'da devlet kurduğunu', 'Avarların Göktürkleri yendiğini'], 'Göktürklerin yükselişi Juan-juanları dağıtmış; batıya kaçanlar Pannonia\'da Avar Kağanlığı\'nı kurmuştur. Bu, bozkır olaylarının Avrupa tarihine doğrudan etkisini gösterir.'),
];
